function inspectionItemLabel(x){let raw=String(x.item||x.label||x[2]||x[0]||'').trim(),m=raw.match(/^Punto\s+(\d+)$/i)||raw.match(/^result-(\d+)$/i);return defaultInspectionItems[m?Number(m[1]):-1]||raw.replace(/^result-/,'Punto ')||'Punto revisado'}
function inspectionReportHtml(i,a){let fam=family(a?.family),rows=(i.answers||[]).map(x=>`<tr><td>${htmlSafe(inspectionItemLabel(x))}</td><td>${htmlSafe(x.result||x.value||x[1]||'')}</td></tr>${(x.note||x[3])?`<tr><td colspan="2"><small>Observación: ${htmlSafe(x.note||x[3])}</small></td></tr>`:''}`).join('')||'<tr><td colspan="2">Sin respuestas registradas</td></tr>';return `<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Inspección ${htmlSafe(a?.code||'')}</title><style>body{font-family:Arial,sans-serif;color:#10251c;margin:32px}header{display:flex;gap:18px;align-items:center;border-bottom:3px solid #0b6b3a;padding-bottom:14px;margin-bottom:22px}header img{width:70px;height:70px;object-fit:contain}.code{font-family:Consolas,monospace;color:#006b3a;font-weight:700}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:18px 0}.box{border:1px solid #d7e2dc;border-radius:10px;padding:12px}small{color:#50635a}table{width:100%;border-collapse:collapse;margin-top:14px}td,th{border:1px solid #d7e2dc;padding:9px;text-align:left}th{background:#eef7f1}.result{font-size:20px;font-weight:700;color:${i.result==='Aprobado'?'#006b3a':'#b42318'}}.signatures{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:28px}.sig{border-top:1px solid #9fb2a8;padding-top:12px;min-height:145px}.sig img{display:block;max-width:260px;max-height:100px;margin:8px 0}.missing{color:#b42318;font-size:13px}@media print{button{display:none}body{margin:18mm}.signatures{break-inside:avoid}}</style></head><body><button onclick="window.print()">Imprimir / guardar como PDF</button><header><img src="logo-icc.jpg"><div><h1>Registro de inspección</h1><div class="code">${htmlSafe(a?.code||'')}</div><small>${htmlSafe(org().name)} · ${htmlSafe(org().label||'Control de Activos')}<br>RUT ${htmlSafe(org().rut)} · ${htmlSafe(org().address)}</small></div></header><div class="grid"><div class="box"><small>Activo</small><br><strong>${htmlSafe(a?.name||'')}</strong></div><div class="box"><small>Familia</small><br>${htmlSafe(fam?.name||'')}</div><div class="box"><small>Fecha</small><br>${htmlSafe(i.date)}</div><div class="box"><small>Resultado</small><br><span class="result">${htmlSafe(i.result)}</span></div><div class="box"><small>Inspector</small><br>${htmlSafe(i.inspector)}</div><div class="box"><small>Revisor / aprobador</small><br>${htmlSafe(i.approver||i.reviewer||'')}</div><div class="box"><small>Proyecto / obra</small><br>${htmlSafe(i.project||a?.location||'')}</div><div class="box"><small>Registro adjunto</small><br>${htmlSafe(i.documentName||'Sin archivo adjunto')}</div></div><h2>Checklist</h2><table><thead><tr><th>Punto revisado</th><th>Resultado</th></tr></thead><tbody>${rows}</tbody></table><h2>Observaciones</h2><p>${htmlSafe(i.notes||'Sin observaciones.')}</p><div class="signatures">${signatureBlock('Firma inspector',i.inspector)}${signatureBlock('Firma aprobador / revisor',i.approver||i.reviewer)}</div><p><small>Documento generado automáticamente por la aplicación el ${new Date().toLocaleString('es-CL')}.</small></p></body></html>`}
function documentsPanel(){ensureInventoryModel();let docs=state.documents.slice(0,30),inspectionForDoc=d=>state.inspections.find(i=>i.id===d.ref);return `<div class="card" style="margin-top:20px"><h2 class="section-title">Documentos y respaldos</h2><p class="page-subtitle">Registro central de facturas, guías, firmas, inspecciones, entregas y documentos generados.</p>${docs.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Documento</th><th>Referencia</th><th>Estado</th><th>Archivo</th></tr></thead><tbody>${docs.map(d=>{let insp=inspectionForDoc(d),download=insp?`<button class="link-button" data-download-inspection="${insp.id}">Descargar inspección PDF</button>${d.fileId?`<br><a class="link-button" href="/api/files/${encodeURIComponent(d.fileId)}" target="_blank">Descargar adjunto</a>`:''}`:d.fileId?`<a class="link-button" href="/api/files/${encodeURIComponent(d.fileId)}" target="_blank">Descargar archivo</a>`:d.content?`<button class="link-button" data-download-doc="${d.id}">Descargar</button>`:'<small>Sin archivo adjunto</small>';return `<tr><td>${d.date||'—'}</td><td>${d.kind||'—'}</td><td><strong>${d.name||'Documento'}</strong><br><small>${[d.code,d.worker,d.center].filter(Boolean).join(' · ')||d.source||''}</small>${d.uploadError?`<br><small style="color:#b00020">Error archivo: ${d.uploadError}</small>`:''}${d.storageProvider?`<br><small>Guardado en: ${d.storageProvider}${d.storagePath?` · ${d.storagePath}`:''}</small>`:''}</td><td>${d.ref||'—'}</td><td>${tag(d.status||'Registrado')}</td><td>${download}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="empty">Aún no hay documentos registrados.</p>'}</div>`}
function downloadGeneratedHtml(name,content){let blob=new Blob([content],{type:'text/html'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(name||'documento').replace(/[^\w.-]+/g,'_')+'.html';a.click();URL.revokeObjectURL(url)}
function blobToDataUrl(blob){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob)})}
async function evidenceImageForInspection(id){let d=state.documents.find(x=>x.ref===id&&x.fileId&&String(x.type||'').startsWith('image/'));if(!d)return '';try{let res=await fetch(`/api/files/${encodeURIComponent(d.fileId)}`);if(!res.ok)return '';return await blobToDataUrl(await res.blob())}catch{return ''}}
async function downloadInspection(id){let i=state.inspections.find(x=>x.id===id),a=state.assets.find(x=>x.id===i?.assetId);if(!i||!a)return toast('No encontramos la inspección.');try{toast('Generando PDF de inspección...');let evidenceImage=await evidenceImageForInspection(id),res=await fetch('/api/inspection/pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organization:org(),asset:a,familyName:family(a.family)?.name||'',inspection:i,inspectorSignature:signatureForPerson(i.inspector),approverSignature:signatureForPerson(i.approver||i.reviewer),evidenceImage})});if(!res.ok){let p=await res.json().catch(()=>({}));throw new Error(p.error||'No se pudo generar PDF')}let blob=await res.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Inspeccion_${a.code}_${i.date}.pdf`;link.click();URL.revokeObjectURL(url)}catch(err){toast(err.message||'No se pudo generar el PDF.');downloadGeneratedHtml(`Inspeccion_${a.code}_${i.date}`,inspectionReportHtml(i,a))}}
function downloadDocument(id){let d=state.documents.find(x=>x.id===id);if(!d)return toast('No encontramos el documento.');let i=state.inspections.find(x=>x.id===d.ref);if(i)return downloadInspection(i.id);if(d.content)return downloadGeneratedHtml(d.name||'documento',d.content);toast('Este registro aún no tiene archivo descargable.')}
async function downloadStoredFile(href,name='archivo'){let res=await fetch(href);if(!res.ok){let payload=await res.json().catch(()=>({}));throw new Error(payload.error||'No se pudo descargar el archivo.')}let blob=await res.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function uploadDocumentFile(doc,file,extra={}){if(!doc||!file||!file.name)return;try{doc.status='Subiendo archivo';save();let dataUrl=await readFileData(file),res=await fetch('/api/files/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,dataUrl,category:doc.kind||'documentos',ref:doc.ref||doc.id,code:doc.code||extra.code||'',center:doc.center||extra.center||'',uploadedBy:activeUser()?.name||'Sistema'})}),payload=await res.json();if(!res.ok)throw new Error(payload.error||'No se pudo subir archivo');doc.fileId=payload.id;doc.storageProvider=payload.provider;doc.storagePath=payload.path||'';doc.downloadUrl=payload.downloadUrl;doc.status='Archivado';audit('Archivo archivado',`${doc.name} · ${payload.provider}`);save();render()}catch(err){doc.status='Pendiente archivo';doc.uploadError=err.message;save();toast('Documento registrado, pero el archivo no se pudo archivar.')}} 
function centerNames(){ensureInventoryModel();return state.costCenters.map(c=>c.name)}
function centerOptions(selected){return centerNames().map(n=>`<option value="${n}" ${n===selected?'selected':''}>${n}</option>`).join('')}
function stockAt(a,center){ensureInventoryModel();return Number(a.stocks?.[center]||0)}
function totalStock(a){ensureInventoryModel();return Object.values(a.stocks||{}).reduce((sum,v)=>sum+Number(v||0),0)}
function setStockAt(a,center,value){ensureInventoryModel();a.stocks[center]=Math.max(0,Number(value||0));a.stock=Object.entries(a.stocks).filter(([k])=>k!=='En tránsito').reduce((sum,[,v])=>sum+Number(v||0),0)}
function moveStock(a,from,to,qty,status){ensureInventoryModel();qty=Math.max(1,Number(qty||1));from=from||a.location||activeUser().costCenter||'Bodega Central';to=to||activeUser().costCenter||'Bodega Central';let landing=status==='En tránsito'?'En tránsito':to;if(a.type==='Consumible'){if(from!==landing)setStockAt(a,from,stockAt(a,from)-qty);setStockAt(a,landing,stockAt(a,landing)+qty);a.status=a.stock<=Number(a.minimum||0)?'Stock bajo':'Disponible'}else{Object.keys(a.stocks).forEach(k=>a.stocks[k]=0);setStockAt(a,landing,1);a.location=landing;a.responsible=landing==='En tránsito'?`En tránsito a ${to}`:to;a.status=landing==='En tránsito'?'En tránsito':'Operativo';a.transferTo=landing==='En tránsito'?to:''}return {from,to,landing,qty}}
function stockSummaryRows(){ensureInventoryModel();return state.assets.map(a=>`<tr><td><strong>${a.name}</strong><br><span class="code">${a.code}</span></td><td><strong>${totalStock(a)}</strong></td>${centerNames().map(c=>`<td>${stockAt(a,c)||''}</td>`).join('')}</tr>`).join('')}
function parseWorker(raw,center){let [name,email,phone]=String(raw||'').split(/[|;]/).map(x=>x.trim());return {name:name||raw,email:email||'',phone:phone||'',center:center.name}}
function allWorkers(){ensureInventoryModel();return state.costCenters.filter(c=>c.name!=='En tránsito').flatMap(c=>(c.workers||[]).map(w=>parseWorker(w,c)))}
function workerOptions(selected,centerName=''){let workers=allWorkers().filter(w=>!centerName||String(w.center).toLowerCase()===String(centerName).toLowerCase());return workers.length?workers.map(w=>`<option value="${w.name}|${w.email}|${w.phone}|${w.center}" ${w.name===selected?'selected':''}>${w.name} · ${w.center}${w.phone?` · ${w.phone}`:w.email?` · ${w.email}`:''}</option>`).join(''):'<option value="">Sin trabajadores enrolados en esta bodega</option>'}
function activeCustody(a){ensureInventoryModel();let legacy=state.assignments.find(x=>x.assetId===a.id&&x.kind==='Activo'&&x.status!=='Devuelto');if(legacy)return legacy;if(!logisticsV2.loaded)return null;let item=canonicalItemForAsset(a),unit=canonicalUnitForAsset(item,a),canonical=(logisticsV2.custody||[]).find(x=>['PENDING','ACTIVE','ACCEPTED'].includes(String(x.status||'').toUpperCase())&&((unit&&String(x.asset_unit_id||'')===String(unit.id))||(!unit&&item&&String(x.item_id||'')===String(item.id))));return canonical?{id:`canonical-${canonical.id}`,canonicalCustodyId:canonical.id,assetId:a.id,kind:'Activo',status:canonical.status,worker:canonical.worker_name||'Trabajador',email:canonical.worker_email||'',phone:canonical.worker_phone||'',from:canonical.warehouse_name||a.location,date:String(canonical.assigned_at||canonical.created_at||'').slice(0,10),canonicalOnly:true}:null}
function eppLabel(a){return isEpp(a)?'Sí, requiere aceptación digital':'No'}
function assignmentUrl(x){return `${location.origin}${location.pathname}?accept=${encodeURIComponent(x.token)}`}
function cleanPhone(value){return String(value||'').replace(/\D/g,'')}
function isEpp(a){return !!a?.isEpp}
function assignmentText(x){let a=findAssetByCode(x?.code);return `ICC PIPING - Registro de entrega a terreno\n\nProducto: ${a?.name||''}\nCódigo: ${x.code}\nCantidad: ${x.qty}\nTipo: ${isEpp(a)?'EPP con aceptación digital':a?.type==='Consumible'?'Consumible entregado':'Activo a cargo informado'}\nTrabajador: ${x.worker}\nCorreo: ${x.email||'No informado'}\nTeléfono: ${x.phone||'No informado'}\nBodega / contrato: ${x.from}\nFecha entrega: ${x.date}\nEntregado por: ${x.issuer}\nEstado: ${x.status}\nFecha aceptación: ${x.acceptedDate||'No aplica / pendiente'}\nAceptado por: ${x.acceptedBy||'No aplica'}\nObservación: ${x.notes||''}\n`;}
function eppRecordHtml(x){let a=findAssetByCode(x?.code),center=costCenter(x.from),workerSig=state.workerSignatures?.[x.worker]||'',advisorSig=center?.safetyAdvisorSignature||'';return `<div class="card"><h1 class="page-title">Acta de recepción E.P.P.</h1><p class="page-subtitle">Registro de recepción conforme generado por Control de Activos ICC.</p><div class="two-col"><div class="card"><h2 class="section-title">Identificación EPP recibido</h2><div class="info-grid"><div class="info-item"><small>Producto</small>${a?.name||''}</div><div class="info-item"><small>Código</small><span class="code">${x.code}</span></div><div class="info-item"><small>Marca</small>${a?.brand||'—'}</div><div class="info-item"><small>Modelo / serie</small>${a?.serial||'—'}</div><div class="info-item"><small>Cantidad</small>${x.qty}</div><div class="info-item"><small>Fecha recepción</small>${x.acceptedDate||x.date}</div></div></div><div class="card"><h2 class="section-title">Identificación trabajador</h2><div class="info-grid"><div class="info-item"><small>Nombre</small>${x.worker}</div><div class="info-item"><small>Correo</small>${x.email||'—'}</div><div class="info-item"><small>Teléfono</small>${x.phone||'—'}</div><div class="info-item"><small>Contrato / bodega</small>${x.from}</div><div class="info-item"><small>Entregado por</small>${x.issuer}</div><div class="info-item"><small>Estado</small>${x.status}</div></div></div></div><div class="card" style="margin-top:20px"><h2 class="section-title">Registro de recepción conforme</h2><div class="table-wrap"><table><thead><tr><th>Fecha recepción</th><th>Cantidad</th><th>Razón de entrega/cambio</th><th>Conformidad</th></tr></thead><tbody><tr><td>${x.acceptedDate||x.date}</td><td>${x.qty}</td><td>${x.notes||'Entrega a terreno'}</td><td>Aceptado digitalmente por ${x.acceptedBy||x.worker}</td></tr></tbody></table></div></div><div class="two-col" style="margin-top:20px"><div class="card"><h2 class="section-title">Firma trabajador</h2>${workerSig?`<img src="${workerSig}" style="max-width:240px;max-height:120px">`:'<p class="empty">Firma no cargada en configuración.</p>'}<p><strong>${x.worker}</strong></p></div><div class="card"><h2 class="section-title">Asesor en prevención</h2>${advisorSig?`<img src="${advisorSig}" style="max-width:240px;max-height:120px">`:'<p class="empty">Firma asesor no cargada.</p>'}<p><strong>${center?.safetyAdvisorName||'Asesor no informado'}</strong></p></div></div></div>`}
function eppPendingAcceptCount(){return state.assignments.filter(x=>isEpp(findAssetByCode(x.code))&&x.status==='Pendiente aceptación').length}
function eppPendingEmailCount(){return state.assignments.filter(x=>isEpp(findAssetByCode(x.code))&&x.status==='Aceptado'&&!x.confirmationSent).length}
function renderEppAdminPanel(){if(route!=='reports'||document.querySelector('[data-epp-admin]'))return;let pending=state.assignments.filter(x=>isEpp(findAssetByCode(x.code))&&x.status==='Pendiente aceptación'),emails=state.assignments.filter(x=>isEpp(findAssetByCode(x.code))&&x.status==='Aceptado'&&!x.confirmationSent);$('#view').insertAdjacentHTML('afterbegin',`<section class="card" data-epp-admin style="margin-bottom:20px"><h2 class="section-title">Control de entregas EPP</h2><div class="two-col"><div><h3 class="section-title">Trabajadores sin aceptar (${pending.length})</h3>${pending.length?pending.map(x=>`<div class="config-item"><div><strong>${x.worker}</strong><small><span class="code">${x.code}</span> · ${x.date}</small></div></div>`).join(''):'<p class="empty">Sin aceptaciones pendientes.</p>'}</div><div><h3 class="section-title">Registros aceptados por enviar (${emails.length})</h3>${emails.length?emails.map(x=>`<div class="config-item"><div><strong>${x.worker}</strong><small><span class="code">${x.code}</span> · aceptado ${x.acceptedDate}</small></div><div class="actions"><a class="button secondary" href="mailto:${x.email}?subject=${encodeURIComponent('Registro firmado EPP '+x.code)}&body=${encodeURIComponent('Se adjunta/informa registro de EPP aceptado digitalmente.\\n\\n'+assignmentText(x))}">Preparar correo</a><button class="button" data-confirmation-sent="${x.id}">Marcar enviado</button></div></div>`).join(''):'<p class="empty">Sin correos pendientes.</p>'}</div></div></section>`)}
function downloadAssignment(id){let x=state.assignments.find(a=>a.id===id);if(!x)return toast('No encontramos el registro.');let blob=new Blob([assignmentText(x)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`entrega-${x.code}-${x.worker}.txt`.replace(/[^\w.-]+/g,'_');a.click();URL.revokeObjectURL(url);toast('Registro descargado.')}
function renderAssignmentDocs(){if(route!=='life'||document.querySelector('[data-assignment-docs]'))return;let asset=state.assets.find(x=>x.id===window.lifeId),docs=state.assignments.filter(x=>x.assetId===asset?.id);if(!asset||!docs.length)return;$('#view').insertAdjacentHTML('beforeend',`<section class="card" data-assignment-docs style="margin-top:20px"><h2 class="section-title">Registros de entrega / cargo</h2>${docs.map(x=>`<div class="config-item"><div><strong>${x.status}</strong><small>${x.date} · ${x.worker} · ${x.qty} ${asset.type==='Consumible'?'unid.':'unidad'}</small></div><button class="button secondary" data-download-assignment="${x.id}">Descargar registro</button></div>`).join('')}</section>`)}
function renderEppFlag(){if(route!=='life'||document.querySelector('[data-epp-flag]'))return;let asset=state.assets.find(x=>x.id===window.lifeId);if(!asset)return;$('#view').insertAdjacentHTML('afterbegin',`<div class="card" data-epp-flag style="margin-bottom:16px"><strong>Clasificación EPP:</strong> ${eppLabel(asset)}</div>`)}
function deliveryModal(id){let a=state.assets.find(x=>x.id===id),from=a.location||activeUser().costCenter||'Bodega Central',custody=activeCustody(a);if(custody)return toast(`Este activo ya está a cargo de ${custody.worker}.`);modal(`Entrega a terreno · ${a.code}`,`<p class="page-subtitle"><strong>${a.name}</strong>. Selecciona trabajador, cantidad y bodega/contrato de origen.</p><form id="terrainForm" data-asset="${id}"><div class="form-grid"><label class="full">Producto<input readonly value="${a.name} · ${a.code}"></label><label>Cantidad<input name="qty" type="number" min="1" value="1" ${a.type==='Activo'?'readonly':''}></label><label>Bodega / contrato<input name="from" readonly value="${htmlSafe(from)}"></label><label class="full">Trabajador<select name="worker" required>${workerOptions('',from)}</select></label><label class="full">Observación<input name="notes" placeholder="Ej. frente de trabajo, guía interna, condición de entrega"></label></div><div class="access-box" style="margin-top:16px">${a.type==='Consumible'?'Consumible: se descuenta del stock y no queda devolución esperada.':'Activo/EPP: no desaparece del stock de la bodega; queda a cargo del trabajador hasta registrar devolución.'}</div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Registrar entrega</button></div></form>`)}
async function returnCustody(id){let a=state.assets.find(x=>x.id===id),c=activeCustody(a),today=new Date().toISOString().slice(0,10);if(!a||!c)return toast('No hay entrega activa para devolver.');try{if(!logisticsV2.loaded)await loadLogisticsV2(true);let canonicalId=c.canonicalCustodyId||(logisticsV2.custody||[]).find(x=>x.external_reference===`legacy-terrain:${c.id}`)?.id;if(!canonicalId)throw new Error('No encontramos la custodia en el modelo V2. Actualiza la conciliación.');await logisticsFetch(`/api/v1/custody/${encodeURIComponent(canonicalId)}/return`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotencyKey:`legacy-terrain:${c.id}:return`,source:'QR',notes:`Devolución registrada por ${activeUser().name}`})});c.canonicalCustodyId=canonicalId;c.status='Devuelto';c.returnedDate=today;c.returnedBy=activeUser().name;a.custodyWorker='';a.custodyEmail='';a.status='Operativo';a.responsible=a.location||activeUser().costCenter||'Bodega Central';state.movements.unshift({id:`m${Date.now()}`,date:today,code:a.code,action:'Devolución desde terreno',user:activeUser().name,from:c.worker,to:a.location,qty:1,status:'Recibido',detail:`Devuelto por ${c.worker}. Activo disponible en ${a.location}.`});await persistState();await loadLogisticsV2(true);toast('Devolución registrada y auditada. Activo disponible.');render()}catch(err){toast(err.message||'No se pudo registrar la devolución.')}}
function acceptanceView(token){let publicData=window.publicAcceptance,x=state.assignments.find(a=>a.token===token)||publicData?.assignment,asset=findAssetByCode(x?.code)||publicData?.asset;if(!x||!asset)return `<div class="card"><h1 class="page-title">Buscando cargo…</h1><p class="page-subtitle">El enlace puede estar incompleto o la entrega aún no fue sincronizada.</p></div>`;return `<div class="heading-row"><div><p class="eyebrow">Aceptación digital</p><h1 class="page-title">Cargo de producto / EPP</h1><p class="page-subtitle">Revisa el detalle y confirma la recepción del producto.</p></div></div><section class="hero"><div><p class="eyebrow">Producto entregado</p><h1>${asset.name}</h1><p><span class="code">${x.code}</span> · Cantidad: ${x.qty}</p></div><div class="qr"><div class="qr-art">✓</div>Aceptar</div></section><div class="card"><form id="acceptCargoForm" data-token="${token}"><div class="info-grid"><div class="info-item"><small>Trabajador</small>${x.worker}</div><div class="info-item"><small>Fecha entrega</small>${x.date}</div><div class="info-item"><small>Entregado por</small>${x.issuer}</div><div class="info-item"><small>Bodega / contrato</small>${x.from}</div><div class="info-item"><small>Estado</small>${x.status}</div><div class="info-item"><small>Observación</small>${x.notes||'—'}</div></div><label style="margin-top:18px">Nombre de quien acepta<input name="acceptedBy" required value="${x.worker}"></label><label style="margin-top:12px"><input type="checkbox" name="ok" required> Acepto haber recibido el producto indicado y mantenerlo bajo mi cargo hasta su devolución o cierre correspondiente.</label><div class="form-actions"><button class="button">Aceptar cargo</button></div></form></div>`}
function acceptanceModal(token){modal('Aceptación de cargo',acceptanceView(token))}
function canonicalPendingTransfers(asset=null){if(!logisticsV2.loaded)return[];let result=[];for(const transfer of logisticsV2.transfers||[]){if(!['IN_TRANSIT','PARTIALLY_RECEIVED'].includes(String(transfer.status||'').toUpperCase()))continue;for(const line of transfer.lines||[]){let qty=Math.max(0,Number(line.dispatched||0)-Number(line.received||0));if(!qty)continue;let matched=state.assets.find(a=>line.unitCode?codeMatches(line.unitCode,a.code):normalizeCode(assetBaseCode(a))===normalizeCode(line.sku));if(!matched||(asset&&matched.id!==asset.id))continue;result.push({id:`v2-receive:${transfer.id}:${line.id}`,canonicalOnly:true,canonicalTransferId:transfer.id,canonicalLineId:line.id,lineReceived:Number(line.received||0),date:String(transfer.dispatched_at||transfer.requested_at||'').slice(0,10),code:matched.code,from:transfer.source_warehouse,to:transfer.destination_warehouse,qty,status:'En tránsito',received:false,action:'Transferencia entre bodegas'})}}return result}
function pendingTransfers(){ensureInventoryModel();let n=0,legacy=state.movements.filter(m=>m.status==='En tránsito'&&!m.received&&!/Proveedor|compra/i.test(`${m.from||''} ${m.action||''}`)).map(m=>{if(!m.id)m.id=`legacy-${normalizeCode(m.code)}-${++n}`;return m}),linked=new Set(legacy.filter(m=>m.canonicalTransferId).map(m=>`${m.canonicalTransferId}|${normalizeCode(m.code)}`));return [...legacy,...canonicalPendingTransfers().filter(m=>!linked.has(`${m.canonicalTransferId}|${normalizeCode(m.code)}`))]}
async function receiveCanonicalTransfer(m,button){let a=findAssetByCode(m?.code);if(!m||!a)return toast('No encontramos el traslado V2.');if(!requirePerm('receive'))return;let qty=Number(m.qty||1),today=new Date().toISOString().slice(0,10);if(button){button.disabled=true;button.textContent='Recibiendo…'}try{await logisticsFetch(`/api/v1/transfers/${encodeURIComponent(m.canonicalTransferId)}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotencyKey:`qr-receive:${m.canonicalTransferId}:${m.canonicalLineId}:${m.lineReceived}`,source:'QR',notes:`Recepción QR por ${activeUser().name}`,lines:[{lineId:m.canonicalLineId,quantity:qty}]})});if(a.type==='Consumible'){setStockAt(a,'En tránsito',Math.max(0,stockAt(a,'En tránsito')-qty));setStockAt(a,m.to,stockAt(a,m.to)+qty);a.status=a.stock<=Number(a.minimum||0)?'Stock bajo':'Disponible'}else{Object.keys(a.stocks).forEach(k=>a.stocks[k]=0);setStockAt(a,m.to,1);a.location=m.to;a.responsible=m.to;a.status='Operativo';a.transferTo=''}state.movements.unshift({id:`m${Date.now()}`,date:today,code:a.code,action:'Recepción de traslado',user:activeUser().name,from:m.from||'En tránsito',to:m.to,qty,status:'Recibido',received:true,detail:`${qty} ${a.type==='Consumible'?'unid.':'unidad'} · Recepción QR conciliada en ${m.to}`,canonicalTransferId:m.canonicalTransferId});await persistState();await loadLogisticsV2(true);toast('Recepción confirmada y conciliada en el libro mayor.');render()}catch(err){toast(err.message||'No se pudo confirmar la recepción.');if(button){button.disabled=false;button.textContent='Confirmar recepción'}}}
function renderPendingTransfers(){let list=pendingTransfers(),mobile=window.matchMedia?.('(max-width: 900px)').matches;if(route!=='dashboard'||mobile||!list.length)return;$('#view').insertAdjacentHTML('beforeend',`<div class="card" style="margin-top:20px"><h2 class="section-title">Pendientes de recepción</h2><p class="page-subtitle">Traslados enviados que aún no han sido confirmados por la bodega destino.</p>${list.map(m=>{let a=findAssetByCode(m.code);return `<div class="config-item"><div><strong><span class="code">${m.code}</span> · ${m.qty} ${a?.type==='Consumible'?'unid.':'unidad'}</strong><small>Desde: ${m.from} · Hacia: ${m.to} · ${m.date}</small></div><button class="button" data-receive="${m.id}">Confirmar recepción</button></div>`}).join('')}</div>`)}
async function receiveTransfer(id){let today=new Date().toISOString().slice(0,10),pending=pendingTransfers(),m=state.movements.find(x=>String(x.id||'')===String(id||''));if(!m)m=pending.find(x=>String(x.id||'')===String(id||'')||String(x.code||'')===String(id||'')||normalizeCode(x.code)===normalizeCode(id));if(!m&&pending.length===1)m=pending[0];let a=findAssetByCode(m?.code);if(!m||!a)return toast('No encontramos el traslado.');let qty=Number(m.qty||1);if(stockAt(a,'En tránsito')<qty)return toast('No hay stock suficiente en tránsito para recibir.');let legacyId=`m${Date.now()}`,v2=null;try{v2=await registerMovementV2({legacyId,a,action:'Recepción de traslado',qty,from:'En tránsito',to:m.to,status:'Recibido',notes:`Recepción del traslado ${m.id||m.code}`})}catch(err){return toast(err.message||'No se pudo recibir en el libro mayor. No se modificó el inventario.')}if(a.type==='Consumible'){setStockAt(a,'En tránsito',stockAt(a,'En tránsito')-qty);setStockAt(a,m.to,stockAt(a,m.to)+qty);a.status=a.stock<=Number(a.minimum||0)?'Stock bajo':'Disponible'}else{Object.keys(a.stocks).forEach(k=>a.stocks[k]=0);setStockAt(a,m.to,1);a.location=m.to;a.responsible=m.to;a.status='Operativo';a.transferTo=''}m.received=true;m.receivedDate=today;m.status='Recibido';state.movements.unshift({id:legacyId,date:today,code:a.code,action:'Recepción de traslado',user:activeUser().name,from:'En tránsito',to:m.to,qty,status:'Recibido',detail:`${qty} ${a.type==='Consumible'?'unid.':'unidad'} · Recibido en ${m.to}`,canonicalTransferId:v2?.transferId||''});save();toast('Recepción registrada en el libro mayor.');render()}
function costCenter(name){return state.costCenters.find(c=>c.name===name)||state.costCenters[0]}
function assetCenter(a){return costCenter(a.location==='Bodega Central'?'Bodega Central':a.location==='Obra Túnel'?'Obra Túnel':activeUser().costCenter)}
function assetUrl(a){return `${location.origin}${location.pathname}?a=${encodeURIComponent(a.code)}`}
function qrImg(value,label){return `<img class="qr-image" src="/api/qr?data=${encodeURIComponent(value)}" alt="QR ${label||value}" loading="lazy">`}
function openAssetFromUrl(){let params=new URLSearchParams(location.search),token=params.get('accept'),code=params.get('a')||params.get('asset')||requestedQrCode||sessionStorage.getItem('icc-pending-qr-code');if(token){window.acceptanceToken=token;route='accept';return true}if(!code)return false;requestedQrCode=code;window.scannedAssetCode=code;let a=findAssetByCode(code);if(!a){route='scan';return true}window.scannedAssetCode=a.code;window.quickAssetId=a.id;window.lifeId=a.id;sessionStorage.removeItem('icc-pending-qr-code');route='quick';return true}
function isPast(date){return date&&new Date(`${date}T23:59:59`)<new Date()}
function refreshBlocks(){state.assets.forEach(a=>{if(a.correctionDue&&isPast(a.correctionDue)&&a.status==='En corrección')a.status='Bloqueado'});save()}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function renderNav(){let visible=activeUserId?nav.filter(n=>n[0]!=='ai'||can('ai')):[]; $('#nav').innerHTML=visible.map(n=>`<button class="nav-button ${route===n[0]?'active':''}" data-route="${n[0]}"><span class="nav-icon">${n[1]}</span>${n[2]}</button>`).join(''); $('#activeUserName').textContent=activeUserId?activeUser().name:'Sin sesión';$('#activeUserRole').textContent=activeUserId?activeUser().role:'Debe ingresar';$('#breadcrumb').textContent=nav.find(n=>n[0]===route)?.[2]||'Control de activos';let actions=$('.top-actions');if($('#userSwitcher'))$('#userSwitcher').textContent=activeUserId?'Cerrar sesión':'Ingresar';if(!activeUserId){$('#eppCounters')?.remove();return}if(actions&&!$('#eppCounters'))actions.insertAdjacentHTML('afterbegin',`<button id="eppCounters" class="outline" data-route="reports" style="color:#b42318;border-color:#f1b8b4">Aceptación: <strong>${eppPendingAcceptCount()}</strong> · Correos: <strong>${eppPendingEmailCount()}</strong></button>`);else if($('#eppCounters'))$('#eppCounters').innerHTML=`Aceptación: <strong>${eppPendingAcceptCount()}</strong> · Correos: <strong>${eppPendingEmailCount()}</strong>`;}
function renderRealtimeCounter(){let actions=$('.top-actions'),open=(window.ICCAuth?.tasks||[]).filter(t=>t.status!=='Resuelta').length,unread=(window.ICCAuth?.notifications||[]).filter(n=>!n.read_at).length,b=$('#realtimeCounters');if(!activeUserId||!window.ICCAuth?.configured){b?.remove();return}if(!b&&actions)actions.insertAdjacentHTML('afterbegin',`<button id="realtimeCounters" class="outline" data-route="tasks"></button>`);b=$('#realtimeCounters');if(b)b.innerHTML=`Tareas: <strong>${open}</strong> · Alertas: <strong>${unread}</strong>`}
function render(){refreshBlocks();renderNav();renderRealtimeCounter(); const views={login:loginView,dashboard,inventory,scan,tasks:tasksView,ai:aiView,quick:quickActions,print:printView,inspections,reports,settings,life,accept:()=>acceptanceView(window.acceptanceToken)}; if(!activeUserId&&route!=='accept')route='login'; if(route==='ai'&&!can('ai'))route='dashboard'; $('#view').innerHTML=views[route]();if(route==='life'){let a=state.assets.find(x=>x.id===window.lifeId),grid=$('.info-grid');if(a&&grid){[['Capas',a.layers],['Ancho',a.width],['Largo',a.length],['Capacidad axial',a.capacity]].filter(x=>x[1]).forEach(x=>grid.insertAdjacentHTML('beforeend',`<div class="info-item"><small>${x[0]}</small>${x[1]}</div>`));$('#view').insertAdjacentHTML('beforeend',`<section class="card scan-card"><div><p class="eyebrow">Lectura con celular</p><h2 class="section-title">QR operativo del activo</h2><p class="page-subtitle">Escanea este QR con la cámara del celular. Primero abrirá las opciones de entrada y salida; desde ahí puedes ir a inspección o Hoja de Vida. Código: <strong class="code">${a.code}</strong>.</p><div class="form-actions"><button class="button" data-start-move="Salida a centro de costo">Registrar salida</button><button class="button secondary" data-start-move="Ingreso a bodega">Registrar ingreso</button><button class="button secondary" data-terrain="${a.id}">Entrega a terreno</button><button class="button secondary" data-route="print">Imprimir etiqueta</button></div></div><div class="qr-panel">${qrImg(assetUrl(a),a.code)}<strong class="code">${a.code}</strong><small>${assetUrl(a)}</small></div></section>`);let reopen=state.inspections.filter(i=>i.assetId===a.id&&i.result==='No aprobado');if(reopen.length)$('#view').insertAdjacentHTML('beforeend',`<section class="card" style="margin-top:20px"><p class="eyebrow">Levantamiento de observaciones</p><h2 class="section-title">Inspecciones abiertas</h2>${reopen.map(i=>`<div class="config-item"><div><strong>Inspección ${i.date}</strong><small>${i.correctionDate?`Corrección registrada: ${i.correctionDate}`:'Pendiente de corrección'}</small></div><button class="button" data-correct="${i.id}">${i.correctionDate?'Ver / actualizar corrección':'Registrar corrección'}</button></div>`).join('')}</section>`)}}if(route==='inspections'&&state.notifications?.length){$('#view').insertAdjacentHTML('afterbegin',`<section class="card" style="margin-bottom:18px"><h2 class="section-title">Notificaciones a revisores</h2>${state.notifications.slice(0,3).map(n=>`<div class="config-item"><div><strong>${n.reviewer}</strong><small>${n.to} · ${n.status}</small></div><a class="button secondary" href="mailto:${n.to}?subject=Revisi%C3%B3n%20de%20inspecci%C3%B3n%20pendiente">Preparar correo</a></div>`).join('')}</section>`) }renderPendingTransfers();if(route==='scan'){$('#movementCode').insertAdjacentHTML('afterend','<button type="button" class="link-button" id="openCode" style="margin-top:7px;text-align:left">Abrir opciones del código escaneado</button>');$('#movementCode').addEventListener('keydown',e=>{if(e.key!=='Enter')return;e.preventDefault();openQuickFromCode($('#movementCode').value)});$('#openCode').onclick=()=>openQuickFromCode($('#movementCode').value)}if(route==='settings'&&window.ICCAuth?.configured){$('#view').insertAdjacentHTML('beforeend',securitySettingsPanels());loadSecurityData()}bind();}
function openQuickFromCode(value){let code=String(value||'').trim().toUpperCase(),a=findAssetByCode(code);if(!a)return toast('No encontramos ese código. Puedes ingresar, por ejemplo, IZA-1 o IZA-000001.');window.quickAssetId=a.id;window.lifeId=a.id;route='quick';render()}
function tuneMovementForm(){let action=$('#movementAction')?.value,userCenter=activeUser().costCenter||'Bodega Central',from=$('#movementFrom'),to=$('#movementTo'),status=$('#movementStatus'),help=$('#movementHelp');if(!action||!from||!to||!status)return;status.disabled=false;if(action==='Ingreso proveedor / compra'){from.value=to.value||userCenter;status.value='Recibido';status.disabled=true;help.textContent='Ingreso externo: suma stock en la bodega destino. No descuenta desde otra bodega y siempre queda recibido.'}else if(action==='Salida a centro de costo'){if(!from.value)from.value='Bodega Central';if(!to.value||to.value===from.value)to.value=userCenter;status.value='En tránsito';help.textContent='Salida: descuenta desde la bodega origen y deja el material en tránsito hasta que destino confirme recepción.'}else if(action==='Transferencia entre bodegas'){status.value='En tránsito';help.textContent='Transferencia: mueve entre bodegas. Primero queda en tránsito y luego se confirma recepción.'}else if(action==='Recepción de traslado'){from.value='En tránsito';status.value='Recibido';if(!to.value)to.value=userCenter;help.textContent='Recepción: toma unidades desde En tránsito y las suma a la bodega destino.'}else if(action==='Devolución a bodega'){status.value='Recibido';if(!to.value)to.value='Bodega Central';help.textContent='Devolución: mueve desde una obra o centro de costo hacia la bodega seleccionada.'}else{status.value='Recibido';help.textContent='Ajuste: corrige o aumenta stock en la bodega destino. Úsalo solo para regularizar inventario.'}}
function quickActionButtons(a,pending,custody,mobile=false){let urgent=[...pending.map(m=>`<button class="button quick-action priority" data-receive="${m.id}">Confirmar recepción · ${m.qty||1} ${a.type==='Consumible'?'unid.':'unidad'}</button>`),custody?`<button class="button quick-action warning" data-return-custody="${a.id}">Registrar devolución desde terreno</button>`:'' ].filter(Boolean).join(''),terrain=custody?'':`<button class="button quick-action primary" data-terrain="${a.id}">Entrega a terreno</button>`;return `<div class="grid quick-actions-grid">${urgent}${terrain}<button class="button quick-action secondary" data-start-move="Salida a centro de costo">Registrar salida</button><button class="button quick-action secondary" data-start-move="Ingreso a bodega">Registrar entrada</button><button class="button quick-action neutral" data-inspect="${a.id}">Inspección</button><button class="button quick-action neutral" data-life="${a.id}">Ficha / Hoja de Vida</button></div>`}
function quickActions(){let a=state.assets.find(x=>x.id===(window.quickAssetId||window.lifeId));if(!a)return scan();ensureInventoryModel();let last=state.movements.find(m=>m.code===a.code),inTransit=stockAt(a,'En tránsito'),pending=pendingTransfers().filter(m=>codeMatches(m.code,a.code)),custody=activeCustody(a),receiveBlock=pending.length?`<div class="card alert-card" style="margin-bottom:20px"><h2 class="section-title">Recepción pendiente</h2><p class="page-subtitle">Este código tiene ${inTransit} ${a.type==='Consumible'?'unid.':'unidad'} en tránsito. Puedes confirmar recepción directamente.</p>${pending.map(m=>`<div class="config-item"><div><strong>${m.qty||1} ${a.type==='Consumible'?'unid.':'unidad'} hacia ${m.to||'destino'}</strong><small>Desde: ${m.from||'origen'} · Fecha envío: ${m.date||'—'}</small></div><button class="button primary" data-receive="${m.id}">Confirmar recepción</button></div>`).join('')}</div>`:'',custodyBlock=custody?`<div class="card alert-card" style="margin-bottom:20px"><h2 class="section-title">A cargo de trabajador</h2><p class="page-subtitle">${a.name} está asignado a <strong>${custody.worker}</strong> desde ${custody.date}. El stock sigue perteneciendo a ${a.location}.</p><button class="button secondary" data-return-custody="${a.id}">Registrar devolución desde terreno</button></div>`:'';return `<section class="quick-mobile-only"><div class="quick-mobile-head"><p class="eyebrow">Acciones rápidas</p><h1 class="page-title">${a.name}</h1><p class="page-subtitle"><span class="code">${a.code}</span> · ${a.location}</p></div>${quickActionButtons(a,pending,custody,true)}</section><div class="quick-desktop-only"><div class="heading-row"><div><p class="eyebrow">Lectura de código</p><h1 class="page-title">${a.name}</h1><p class="page-subtitle"><span class="code">${a.code}</span> · ${family(a.family)?.name||'Sin familia'} · ${a.location}</p></div></div>${receiveBlock}${custodyBlock}<section class="hero"><div><p class="eyebrow">Acción rápida</p><h1>¿Qué deseas hacer con este código?</h1><p>Primero aparecen las acciones de bodega y terreno. Luego puedes abrir inspección o ficha del equipo.</p></div><div class="qr"><div class="qr-art">⌁</div>${a.code}</div></section>${quickActionButtons(a,pending,custody)}<div class="card" style="margin-top:20px"><h2 class="section-title">Resumen del activo</h2><div class="info-grid"><div class="info-item"><small>Estado</small>${tag(a.status)}</div><div class="info-item"><small>Ubicación actual</small>${a.location}</div><div class="info-item"><small>Responsable</small>${a.responsible}</div><div class="info-item"><small>Disponible empresa</small>${a.stock ?? 1}</div><div class="info-item"><small>En tránsito</small>${inTransit}</div><div class="info-item"><small>A cargo de</small>${custody?.worker||'—'}</div><div class="info-item"><small>Serie</small>${a.serial||'—'}</div><div class="info-item"><small>Último movimiento</small>${last?`${last.action} · ${last.date}`:'Sin movimientos'}</div></div></div></div>`}
function dashboard(){ensureInventoryModel();const serial=state.assets.filter(a=>a.type==='Activo');const low=state.assets.filter(a=>a.type==='Consumible'&&a.stock<=a.minimum);const due=serial.filter(a=>a.nextInspection&&a.nextInspection<='2026-06-30');return `<section class="mobile-dashboard-actions card"><p class="eyebrow">Operación móvil</p><h1 class="page-title">Acciones rápidas</h1><p class="page-subtitle">Selecciona la operación que deseas realizar.</p><div class="grid"><button class="button quick-action primary" data-route="scan">Escanear / registrar movimiento</button><button class="button quick-action neutral" data-route="inspections">Realizar inspección</button><button class="button quick-action neutral" data-route="inventory">Consultar inventario</button></div></section><div class="desktop-dashboard-full"><div class="heading-row"><div><p class="eyebrow">Panel operativo</p><h1 class="page-title">Hola, ${activeUser().name.split(' ')[0]}</h1><p class="page-subtitle">Una vista clara para mantener equipos seguros y materiales disponibles.</p></div><button class="button" data-action="newAsset">＋ Registrar activo</button></div><div class="grid metrics"><div class="card"><div class="metric-label">Activos serializados</div><div class="metric-value">${serial.length}</div><div class="metric-foot">Con código y Hoja de Vida</div></div><div class="card"><div class="metric-label">Inspecciones próximas</div><div class="metric-value">${due.length}</div><div class="metric-foot ${due.length?'alert':''}">${due.length?'Requieren atención':'Todo al día'}</div></div><div class="card"><div class="metric-label">Consumibles</div><div class="metric-value">${state.assets.filter(a=>a.type==='Consumible').length}</div><div class="metric-foot">Control por cantidad</div></div><div class="card"><div class="metric-label">Stock bajo</div><div class="metric-value">${low.length}</div><div class="metric-foot ${low.length?'alert':''}">${low.length?'Reponer pronto':'Sin alertas'}</div></div></div><div class="grid dashboard-grid"><div class="card"><h2 class="section-title">Actividad reciente</h2>${state.movements.slice(0,5).map(m=>`<div class="timeline-item"><strong>${m.action}</strong><div><span class="code">${m.code}</span> · ${m.detail}</div><small>${m.date} · ${m.user}</small></div>`).join('')}</div><div class="card"><h2 class="section-title">Acciones rápidas</h2><div class="grid"><button class="button" data-route="scan">Escanear / registrar movimiento</button><button class="button secondary" data-route="inspections">Realizar inspección</button><button class="button secondary" data-route="inventory">Consultar inventario</button></div></div></div><div class="card" style="margin-top:20px"><h2 class="section-title">Inventario por bodega / centro de costo</h2><div class="table-wrap"><table><thead><tr><th>Activo / material</th><th>Total empresa</th>${centerNames().map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${stockSummaryRows()}</tbody></table></div></div></div>`}
function tasksView(){let tasks=window.ICCAuth?.tasks||[],notifications=window.ICCAuth?.notifications||[],open=tasks.filter(t=>t.status!=='Resuelta'),resolved=tasks.filter(t=>t.status==='Resuelta').slice(0,15),taskCard=t=>`<div class="critical-task ${String(t.priority).toLowerCase()==='crítica'?'critical':''}"><div><div class="task-heading"><span class="task-priority">${htmlSafe(t.priority)}</span><strong>${htmlSafe(t.title)}</strong></div><p>${htmlSafe(t.detail||'')}</p><small>${htmlSafe(t.center_name||'')} ${t.due_at?`· Vence: ${new Date(t.due_at).toLocaleDateString('es-CL')}`:''}</small></div><div class="actions">${t.status==='Pendiente'?`<button class="button secondary" data-task-status="En proceso" data-task-id="${t.id}">Tomar tarea</button>`:''}${t.status!=='Resuelta'?`<button class="button" data-task-status="Resuelta" data-task-id="${t.id}">Resolver</button>`:''}</div></div>`,notificationCard=n=>`<div class="notification-row ${n.read_at?'read':''}"><div><strong>${htmlSafe(n.title)}</strong><p>${htmlSafe(n.body||'')}</p><small>${new Date(n.created_at).toLocaleString('es-CL')} · ${htmlSafe(n.center_name||'')}</small></div>${n.read_at?'':`<button class="link-button" data-notification-read="${n.id}">Marcar leída</button>`}</div>`;return `<div class="heading-row"><div><p class="eyebrow">Supabase Realtime</p><h1 class="page-title">Tareas críticas y notificaciones</h1><p class="page-subtitle">Los cambios aparecen automáticamente en los equipos conectados.</p></div><button class="outline" data-refresh-realtime>Actualizar</button></div><div class="grid metrics"><div class="card"><div class="metric-label">Tareas abiertas</div><div class="metric-value">${open.length}</div></div><div class="card"><div class="metric-label">Prioridad crítica</div><div class="metric-value">${open.filter(t=>t.priority==='Crítica').length}</div></div><div class="card"><div class="metric-label">Alertas sin leer</div><div class="metric-value">${notifications.filter(n=>!n.read_at).length}</div></div><div class="card"><div class="metric-label">Resueltas recientes</div><div class="metric-value">${resolved.length}</div></div></div><div class="two-col"><section class="card"><h2 class="section-title">Pendientes</h2>${open.length?open.map(taskCard).join(''):'<p class="empty">No hay tareas pendientes.</p>'}</section><section class="card"><h2 class="section-title">Notificaciones</h2>${notifications.length?notifications.slice(0,30).map(notificationCard).join(''):'<p class="empty">No hay notificaciones.</p>'}</section></div>${resolved.length?`<section class="card" style="margin-top:20px"><h2 class="section-title">Tareas resueltas</h2>${resolved.map(taskCard).join('')}</section>`:''}`}
function reports(){ensureInventoryModel();let consumidos=state.movements.filter(m=>/Salida|Egreso/i.test(m.action||'')&&m.status!=='En tránsito'),recibidos=state.movements.filter(m=>/Recepción|Ingreso/i.test(m.action||'')&&m.status==='Recibido'),pendientes=pendingTransfers(),low=state.assets.filter(a=>a.type==='Consumible'&&Number(a.minimum||0)>0&&a.stock<=a.minimum),byCenter={};consumidos.forEach(m=>{let k=m.to||m.from||'Sin destino';byCenter[k]=(byCenter[k]||0)+Number(m.qty||1)});let byRows=Object.entries(byCenter).sort((a,b)=>b[1]-a[1]);let topMov=state.movements.slice(0,12);return `<div class="heading-row"><div><p class="eyebrow">Control y estadísticas</p><h1 class="page-title">Reportes</h1><p class="page-subtitle">Resumen para Bodega Central: consumo, stock por centro de costo, pendientes, alertas y documentos.</p></div><button class="button" data-export-report>Exportar CSV</button></div><div class="grid metrics"><div class="card"><div class="metric-label">Salidas registradas</div><div class="metric-value">${consumidos.length}</div><div class="metric-foot">Movimientos de consumo/egreso</div></div><div class="card"><div class="metric-label">Recepciones</div><div class="metric-value">${recibidos.length}</div><div class="metric-foot">Ingresos confirmados</div></div><div class="card"><div class="metric-label">Pendientes en tránsito</div><div class="metric-value">${pendientes.length}</div><div class="metric-foot ${pendientes.length?'alert':''}">${pendientes.length?'Requieren recepción':'Sin pendientes'}</div></div><div class="card"><div class="metric-label">Stock bajo</div><div class="metric-value">${low.length}</div><div class="metric-foot ${low.length?'alert':''}">${low.length?'Reponer pronto':'Sin alertas'}</div></div></div><div class="two-col"><div class="card"><h2 class="section-title">Consumo / salidas por centro de costo</h2>${byRows.length?`<div class="table-wrap"><table><thead><tr><th>Centro de costo</th><th>Cantidad movida</th></tr></thead><tbody>${byRows.map(r=>`<tr><td>${r[0]}</td><td><strong>${r[1]}</strong></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Aún no hay salidas registradas.</p>'}</div><div class="card"><h2 class="section-title">Pendientes en tránsito</h2>${pendientes.length?pendientes.map(m=>`<div class="config-item"><div><strong><span class="code">${m.code}</span> · ${m.qty||1}</strong><small>${m.from||'Origen'} → ${m.to||'Destino'} · ${m.date||'—'}</small></div><button class="button" data-receive="${m.id}">Recibir</button></div>`).join(''):'<p class="empty">No hay materiales en tránsito.</p>'}</div></div><div class="card" style="margin-top:20px"><h2 class="section-title">Stock actual por bodega / centro de costo</h2><div class="table-wrap"><table><thead><tr><th>Activo / material</th><th>Total empresa</th>${centerNames().map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${stockSummaryRows()}</tbody></table></div></div><div class="two-col" style="margin-top:20px"><div class="card"><h2 class="section-title">Alertas de stock bajo</h2>${low.length?low.map(a=>`<div class="config-item"><div><strong>${a.name}</strong><small><span class="code">${a.code}</span> · Stock ${a.stock} · Mínimo ${a.minimum}</small></div>${tag('Stock bajo')}</div>`).join(''):'<p class="empty">Sin alertas de stock bajo.</p>'}</div><div class="card"><h2 class="section-title">Últimos movimientos</h2>${topMov.length?topMov.map(m=>`<div class="timeline-item"><strong>${m.action}</strong><div><span class="code">${m.code}</span> · ${m.detail||''}</div><small>${m.date||'—'} · ${m.user||'—'}</small></div>`).join(''):'<p class="empty">Sin movimientos registrados.</p>'}</div></div>${documentsPanel()}`}
function exportReport(){ensureInventoryModel();let rows=[['codigo','activo_material','tipo','familia','total_empresa',...centerNames()]];state.assets.forEach(a=>rows.push([a.code,a.name,a.type,family(a.family)?.name||'',totalStock(a),...centerNames().map(c=>stockAt(a,c))]));let csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`reporte-inventario-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url);toast('Reporte CSV generado.')}
function aiView(){ensureInventoryModel();let docs=state.aiDrafts.slice(0,8);return `<div class="heading-row"><div><p class="eyebrow">IA controlada</p><h1 class="page-title">Digitalizar documentos</h1><p class="page-subtitle">Sube factura, guía o inspección. La IA propone datos; tú confirmas antes de modificar inventario o plantillas.</p></div></div><div class="two-col"><div class="card"><h2 class="section-title">Nuevo análisis</h2><form id="aiForm"><div class="form-grid"><label>Tipo de documento<select name="kind"><option value="purchase">Factura / guía de despacho</option><option value="inspection">Formulario de inspección</option></select></label><label>Bodega destino<select name="center">${centerOptions(activeUser().costCenter||'Bodega Central')}</select></label><label class="full">Archivo<input name="file" type="file" accept="image/*,.pdf" required><small>Fotos claras o PDF. La clave OpenAI se usa sólo en el servidor.</small></label></div><div class="form-actions"><button class="button">Analizar con IA</button></div></form><div id="aiStatus" class="access-box" style="display:none;margin-top:16px"></div></div><div class="card"><h2 class="section-title">Reglas de seguridad</h2><p class="page-subtitle">La IA no registra stock por sí sola. Cada línea queda como borrador pendiente de confirmación.</p><ul><li>Coincidencia alta: propone código existente.</li><li>Coincidencia baja: solicita creación manual.</li><li>Inspecciones: genera plantilla editable antes de usar en celular.</li></ul></div></div><div class="card" style="margin-top:20px"><h2 class="section-title">Borradores IA</h2>${docs.length?docs.map(aiDraftCard).join(''):'<p class="empty">Aún no hay documentos analizados.</p>'}</div>`}
function aiDraftCard(d){let lines=d.kind==='purchase'?(d.result?.items||[]):[],checks=d.kind==='inspection'?(d.result?.checklist||[]):[];return `<div class="config-item ai-draft"><div><strong>${d.filename}</strong><small>${d.kind==='purchase'?'Factura / guía':'Inspección'} · ${d.date} · Estado: ${d.status}</small>${lines.length?`<div style="margin-top:8px">${lines.slice(0,4).map(x=>`<div><span class="code">${x.suggestedCode||'Sin código'}</span> · ${x.description||'Producto'} · ${x.quantity||1} ${x.unit||''} · confianza ${Math.round((x.confidence||0)*100)}%</div>`).join('')}</div>`:''}${checks.length?`<div style="margin-top:8px">${checks.slice(0,5).map(x=>`<div>✓ ${x.item||x}</div>`).join('')}</div>`:''}</div><div class="actions">${d.kind==='purchase'?`<button class="button secondary" data-confirm-ai-purchase="${d.id}">Confirmar ingreso</button>`:`<button class="button secondary" data-confirm-ai-inspection="${d.id}">Crear plantilla</button>`}</div></div>`}
function inventory(){let q=assetFilter.toLowerCase(),nq=normalizeCode(assetFilter);let rows=state.assets.filter(a=>((a.name+a.code).toLowerCase().includes(q)||codeMatches(a.code,nq))&&(familyFilter==='all'||a.family===familyFilter));return `<div class="heading-row"><div><p class="eyebrow">Catálogo y existencias</p><h1 class="page-title">Inventario</h1><p class="page-subtitle">Los activos tienen Hoja de Vida; los consumibles se controlan por stock. Haz clic en el código para agregar unidades iguales.</p></div><button class="button" data-action="newAsset">＋ Registrar</button></div><div class="filter-row"><input id="search" value="${assetFilter}" placeholder="Buscar por nombre o código"/><select id="familyFilter"><option value="all">Todas las familias</option>${state.families.map(f=>`<option value="${f.id}" ${familyFilter===f.id?'selected':''}>${f.name}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Activo / material</th><th>Familia</th><th>Situación</th><th>Ubicación</th><th></th></tr></thead><tbody>${rows.length?rows.map(a=>`<tr><td><button class="link-button code" data-clone-asset="${a.id}" title="Agregar activos iguales">${a.code}</button></td><td><strong>${a.name}</strong><br><small>${a.type==='Activo'?`Serie: ${a.serial||'—'}${a.unitCount>1?` · Unidad ${a.unitNo} de ${a.unitCount}`:''}`:`Stock: ${a.stock} ${a.minimum?`· Mín. ${a.minimum}`:''}`}</small></td><td>${family(a.family)?.name||'—'}</td><td>${tag(a.status)}</td><td>${a.location}</td><td><button class="link-button" data-life="${a.id}">${a.type==='Activo'?'Ver Hoja de Vida':'Ver detalle'}</button></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No hay resultados.</td></tr>`}</tbody></table></div>`}
function scan(){let userCenter=activeUser().costCenter||'Bodega Central',a=scannedAsset(),code=a?.code||window.scannedAssetCode||requestedQrCode||'',identified=a?`<div class="scan-product-summary"><span>Producto identificado por QR</span><strong>${htmlSafe(a.name)}</strong><small><span class="code">${htmlSafe(a.code)}</span> · ${htmlSafe(a.location||'Sin ubicación')}</small></div>`:'';return `<div class="heading-row"><div><p class="eyebrow">Operación rápida</p><h1 class="page-title">Registrar movimiento</h1><p class="page-subtitle">${a?'Completa la operación del producto escaneado.':'Escanea o ingresa el código. El sistema descontará desde una bodega y sumará en destino o tránsito.'}</p><p class="mobile-note">Puedes usar la cámara del teléfono o pistola lectora como teclado.</p></div></div><div class="card movement-card">${identified}<form id="movementForm"><div class="form-grid"><label class="full">Código del activo o material<input id="movementCode" required value="${htmlSafe(code)}" placeholder="Ej. IZA-000001" ${a?'readonly':'autofocus'}></label><label>Operación<select id="movementAction"><option>Salida a centro de costo</option><option>Ingreso proveedor / compra</option><option>Transferencia entre bodegas</option><option>Recepción de traslado</option><option>Devolución a bodega</option><option>Ajuste de stock</option></select></label><label>Cantidad<input id="movementQty" type="number" min="1" value="1"></label><label>Desde<select id="movementFrom">${centerOptions(a?.location||userCenter)}</select></label><label>Hacia<select id="movementTo">${centerOptions(userCenter)}</select></label><label>Estado<select id="movementStatus"><option>Recibido</option><option>En tránsito</option></select></label><label class="full">Observación / documento<input id="movementDetail" placeholder="Ej. guía, factura, responsable, comentario"></label></div><div id="movementHelp" class="access-box" style="margin-top:16px"></div><div class="form-actions"><button class="button">Registrar movimiento</button></div></form></div>`}
const code39Patterns={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','C':'wnwnnwnnn','E':'wnnnwwnnn','I':'nnwnnwwnn','L':'nnwnnnnww','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Z':'nwwnwnnnn','-':'nwnnnnwnw','*':'nwnnwnwnn'};
function code39Svg(value){let bits=`*${value}*`,x=8,rects=[];for(const char of bits){let p=code39Patterns[char]||code39Patterns['-'];for(let i=0;i<p.length;i++){let w=p[i]==='w'?5:2;if(i%2===0)rects.push(`<rect x="${x}" y="5" width="${w}" height="62"/>`);x+=w}x+=3}return `<svg class="barcode" viewBox="0 0 ${x+8} 72" role="img" aria-label="Código de barras ${value}" preserveAspectRatio="none">${rects.join('')}</svg>`}
function printView(){let selected=window.printAssetId||window.lifeId||state.assets[0].id,a=state.assets.find(x=>x.id===selected);return `<div class="heading-row print-hide"><div><p class="eyebrow">Etiquetado de activos</p><h1 class="page-title">Imprimir etiquetas QR</h1><p class="page-subtitle">Selecciona un activo: la etiqueta imprime el código legible y un QR directo a la Hoja de Vida.</p></div></div><div class="print-layout"><div class="card print-hide"><label>Activo / material<select id="printAsset">${state.assets.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${x.code} · ${x.name}</option>`).join('')}</select></label><div class="info-item" style="margin-top:16px"><small>Código a imprimir</small><strong class="code" style="font-size:20px">${a.code}</strong></div><div class="info-item" style="margin-top:10px"><small>Destino del QR</small><strong style="font-size:12px;word-break:break-all">${assetUrl(a)}</strong></div><div class="form-actions"><button type="button" class="button" id="printButton" onclick="window.print()">Imprimir etiqueta</button></div><p class="page-subtitle">Compatible con hoja adhesiva o impresora de etiquetas configurada en el equipo.</p></div><section class="label-sheet"><div class="print-label qr-label"><img src="logo-icc.jpg" alt="ICC Piping" class="label-logo"><div class="label-content"><strong>ICC PIPING · CONTROL DE ACTIVOS</strong><span>${a.name}</span><b>${a.code}</b><small>${a.type==='Activo'?`Serie: ${a.serial||'No registrada'}`:`Material consumible · Stock: ${a.stock}`}</small></div><div class="label-qr">${qrImg(assetUrl(a),a.code)}</div></div><p class="print-hide label-note">Vista previa de etiqueta QR · ${a.code}</p></section></div>`}
function inspections(){let items=state.assets.filter(a=>a.type==='Activo');let pending=state.inspections.filter(i=>i.result==='No aprobado'&&!i.correctionDue);return `<div class="heading-row"><div><p class="eyebrow">Seguridad y trazabilidad</p><h1 class="page-title">Inspecciones</h1><p class="page-subtitle">Cada inspección exige un registro digital y queda vinculada a la Hoja de Vida.</p></div></div>${pending.length?`<div class="card" style="margin-bottom:18px"><h2 class="section-title">Pendientes de plazo por aprobador</h2>${pending.map(i=>{let a=state.assets.find(x=>x.id===i.assetId);return `<div class="config-item"><div><strong>${a?.name||'Equipo'} · <span class="code">${a?.code||''}</span></strong><small>Aprobador asignado: ${i.approver} · Inspección ${i.date}</small></div><button class="button" data-deadline="${i.id}">Definir plazo</button></div>`}).join('')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>Equipo</th><th>Tipo</th><th>Próxima inspección</th><th>Estado</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${a.name}</strong><br><span class="code">${a.code}</span></td><td>${family(a.family)?.inspection||'General'}</td><td>${a.correctionDue?`Corrección: ${a.correctionDue}`:a.nextInspection||'Sin periodicidad'}</td><td>${tag(a.status)}</td><td><button class="button" data-inspect="${a.id}">Inspeccionar</button></td></tr>`).join('')}</tbody></table></div>`}
function centerCard(c){return `<div class="config-item"><div><strong>${c.name}</strong><small>Inspectores: ${c.inspectors.join(', ')||'Sin definir'} · Aprobadores: ${c.approvers.join(', ')||'Sin definir'}</small></div><button class="link-button" data-edit-center="${c.id}">Gestionar listas</button></div>`}
function settings(){let canAdmin=activeUser().admin,o=org(),centers=canAdmin?state.costCenters:[costCenter(activeUser().costCenter)],orgCard=canAdmin?`<div class="card settings-wide"><h2 class="section-title">Datos de la organización</h2><p class="page-subtitle">Estos datos se usan en certificados, inspecciones, entregas y respaldos.</p><div class="info-grid"><div class="info-item"><small>Razón social</small>${o.name}</div><div class="info-item"><small>RUT</small>${o.rut}</div><div class="info-item"><small>Dirección</small>${o.address}</div><div class="info-item"><small>Nombre sistema</small>${o.label||'Control de Activos'}</div></div><div class="form-actions" style="justify-content:flex-start"><button class="button secondary" data-action="organization">Editar organización</button></div></div>`:'',usersCard=canAdmin&&!window.ICCAuth?.configured?`<div class="card settings-wide"><h2 class="section-title">Usuarios</h2><p class="page-subtitle">Usa este botón sólo para crear una nueva persona con acceso. Las firmas de trabajadores se gestionan dentro de cada bodega o centro de costo.</p><div class="form-actions" style="justify-content:flex-start"><button class="button" data-action="newUser">＋ Agregar usuario</button></div></div>`:'';return `<div class="heading-row"><div><p class="eyebrow">${canAdmin?'Administración':'Mi centro de costo'}</p><h1 class="page-title">Configuración</h1><p class="page-subtitle">${canAdmin?'Configuración global de la aplicación.':'Gestiona las listas de inspectores y aprobadores de tu centro de costo.'}</p></div></div>${orgCard}<div class="two-col"><div class="card"><h2 class="section-title">Inspectores y aprobadores</h2><p class="page-subtitle">Los nombres se muestran como listas desplegables en cada inspección.</p><div class="config-list">${centers.map(centerCard).join('')}</div>${canAdmin?'<div class="form-actions"><button class="button" data-action="newCenter">＋ Crear bodega / centro de costo</button></div>':''}</div>${canAdmin?`<div class="card"><h2 class="section-title">Familias de inventario</h2><div class="config-list">${state.families.map(f=>`<div class="config-item"><div><strong>${f.name}</strong><small>Prefijo ${f.prefix} · ${f.serial?'Activo serializado':'Consumible por stock'}</small></div><button class="link-button" data-edit-family="${f.id}">Editar</button></div>`).join('')}</div><div class="form-actions"><button class="button" data-action="newFamily">＋ Agregar familia</button></div></div>`:''}</div>${usersCard}`}
function life(){let a=state.assets.find(x=>x.id===window.lifeId); if(!a)return dashboard();let logs=state.inspections.filter(i=>i.assetId===a.id);return `<div class="heading-row"><div><button class="link-button" data-route="inventory">← Volver al inventario</button><p class="eyebrow" style="margin-top:15px">Hoja de Vida</p><h1 class="page-title">${a.name}</h1><p class="page-subtitle"><span class="code">${a.code}</span> · ${family(a.family)?.name}</p></div><button class="button" data-inspect="${a.id}">Realizar inspección</button></div><div class="hero"><div><p class="eyebrow">Estado actual</p><h1>${a.status}</h1><p>${a.correctionDue?`Corrección exigida antes del ${a.correctionDue}`:a.type==='Activo'?'Activo serializado y trazable':'Consumible por stock'}</p></div><div class="qr"><div class="qr-art">▦</div>${a.code}</div></div><div class="two-col"><div class="card"><h2 class="section-title">Identificación</h2><div class="info-grid"><div class="info-item"><small>Marca</small>${a.brand||'—'}</div><div class="info-item"><small>Número de serie</small>${a.serial||'—'}</div><div class="info-item"><small>Responsable</small>${a.responsible}</div><div class="info-item"><small>Ubicación</small>${a.location}</div><div class="info-item"><small>Próxima inspección</small>${a.correctionDue||a.nextInspection||'—'}</div><div class="info-item"><small>Tipo</small>${a.type}</div></div></div><div class="card"><h2 class="section-title">Historial de inspecciones</h2>${logs.length?logs.map(i=>`<div class="timeline-item"><strong>${tag(i.result)} ${i.date}</strong><div>${i.notes||'Sin observaciones'}</div><small>Inspector: ${i.inspector} · Aprobador: ${i.approver||'—'}<br>Registro digital: ${i.documentName||'No informado'}${i.correctionDue?`<br>Plazo: ${i.correctionDue}`:''}</small></div>`).join(''):'<p class="empty">Aún no hay inspecciones.</p>'}</div></div><div class="card" style="margin-top:20px"><h2 class="section-title">Movimientos recientes</h2>${state.movements.filter(m=>m.code===a.code).map(m=>`<div class="timeline-item"><strong>${m.action}</strong><div>${m.detail}</div><small>${m.date} · ${m.user}</small></div>`).join('')||'<p class="empty">Sin movimientos registrados.</p>'}</div>`}
function closeModal(){let m=$('#modal');if(m){m.className='modal-root';m.innerHTML=''}}
function modal(title, body){$('#modal').className='modal-root open';$('#modal').innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="close" data-close>×</button></div><div class="modal-body">${body}</div></div>`}
function organizationModal(){let o=org();modal('Datos de la organización',`<form id="organizationForm"><div class="form-grid"><label class="full">Razón social<input name="name" required value="${htmlSafe(o.name)}"></label><label>RUT<input name="rut" required value="${htmlSafe(o.rut)}"></label><label>Nombre del sistema<input name="label" value="${htmlSafe(o.label||'Control de Activos')}"></label><label class="full">Dirección<input name="address" required value="${htmlSafe(o.address)}"></label></div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Guardar organización</button></div></form>`)}
function assetModal(){let opts=state.families.map(f=>`<option value="${f.id}">${f.name}</option>`).join('');modal('Registrar activo o material',`<form id="assetForm"><div class="form-grid"><label>Familia<select id="assetFamily">${opts}</select></label><label>Clase<select id="assetType"><option value="Activo">Activo no consumible</option><option value="Consumible">Consumible</option></select></label><label class="full"><input id="assetIsEpp" type="checkbox"> Este producto es EPP y requiere aceptación digital del trabajador al entregarlo a terreno</label><label class="full">Nombre / descripción<input id="assetName" required placeholder="Ej. Soldadora inverter 200A"></label><label>Marca<input id="assetBrand" placeholder="Marca"></label><label>Número de serie<input id="assetSerial" placeholder="Para activos"></label><label>Cantidad de unidades iguales<input id="assetUnits" type="number" min="1" value="1"><small>Para activos iguales: 5 soldadoras generan 5 códigos con verificador.</small></label><label>Capas<input id="assetLayers" placeholder="Ej. 2 capas"></label><label>Ancho<input id="assetWidth" placeholder="Ej. 2 pulgadas"></label><label>Largo<input id="assetLength" placeholder="Ej. 6 metros"></label><label>Capacidad axial<input id="assetCapacity" placeholder="Ej. 6 toneladas"></label><label>Ubicación inicial<select id="assetLocation">${centerOptions('Bodega Central')}</select></label><label>Stock inicial<input id="assetStock" type="number" min="1" value="1"></label><label class="full">Stock mínimo (sólo consumibles)<input id="assetMin" type="number" min="0" value="0"></label></div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Guardar y generar código</button></div></form>`)}
function cloneAssetModal(id){let a=state.assets.find(x=>x.id===id);if(!a)return toast('No encontramos el activo.');if(a.type!=='Activo')return toast('Esta opción aplica a activos no consumibles.');modal(`Agregar iguales · ${a.code}`,`<p class="page-subtitle">Se crearán activos iguales a <strong>${a.name}</strong>, con el mismo código base y un dígito verificador por unidad.</p><form id="cloneAssetForm" data-id="${id}"><div class="form-grid"><label class="full">Activo base<input readonly value="${a.name} · ${a.code}"></label><label>Cantidad adicional<input name="qty" type="number" min="1" value="1" required></label><label>Ubicación inicial<select name="location">${centerOptions(a.location||'Bodega Central')}</select></label></div><div class="access-box" style="margin-top:16px">Ejemplo: si el código base es ELE-000010, las nuevas unidades quedarán como ELE-000010-2, ELE-000010-3, etc.</div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Crear unidades iguales</button></div></form>`)}
function inspectionModal(id){let a=state.assets.find(x=>x.id===id),center=assetCenter(a);let rows=['Etiqueta o marcaje legible (WLL)','Sin cortes, desgaste o deformaciones','Sin corrosión excesiva','Uso acorde al ángulo de izaje','Ganchos con seguro operativo','Sin fisuras, deformaciones o desgaste','Capacidad compatible con la carga'];modal(`Inspección móvil · ${a.code}`,`<p class="page-subtitle">${a.name}. Completa los puntos aplicables, adjunta el registro digital y registra observaciones.</p><form id="inspectionForm" data-asset="${id}"><div class="form-grid"><label>Proyecto / obra<input name="project" placeholder="Ej. Túnel"></label><label>Inspector<select name="inspector" required>${center.inspectors.map(n=>`<option ${n===activeUser().name?'selected':''}>${n}</option>`).join('')}</select></label><label class="full">Aprobador responsable<select name="approver" required>${center.approvers.map(n=>`<option>${n}</option>`).join('')}</select></label><label class="full">Registro digital de inspección<input name="document" type="file" accept="application/pdf,image/*,.doc,.docx" required><small>Obligatorio: PDF, foto o documento digital del registro.</small></label></div><div class="inspection-section">Checklist de equipos de izaje</div>${rows.map((r,i)=>`<div class="check-row"><strong>${r}</strong><input type="hidden" name="item-${i}" value="${htmlSafe(r)}"><select name="result-${i}"><option value="Cumple">Cumple</option><option value="No cumple">No cumple</option><option value="No aplica">No aplica</option></select><input name="note-${i}" placeholder="Observación (opcional)"></div>`).join('')}<label style="margin-top:16px">Conclusión / observaciones generales<textarea name="notes" placeholder="Detalle, acción correctiva o evidencia."></textarea></label><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Guardar inspección</button></div></form>`) }
function centerModal(id){let c=state.costCenters.find(x=>x.id===id),workers=(c.workers||[]).map(w=>parseWorker(w,c));modal(`Listas · ${c.name}`,`<p class="page-subtitle">Trabajadores formato: Nombre Apellido | correo@empresa.cl | 56912345678. La firma se carga al lado de cada trabajador.</p><form id="centerForm" data-id="${id}"><div class="form-grid"><label>Inspectores<textarea name="inspectors" required placeholder="Nombre Apellido">${c.inspectors.join('\n')}</textarea></label><label>Aprobadores<textarea name="approvers" required placeholder="Nombre Apellido">${c.approvers.join('\n')}</textarea></label><label class="full">Trabajadores del contrato / centro<textarea name="workers" placeholder="Nombre Apellido | correo@empresa.cl | 56912345678">${(c.workers||[]).join('\n')}</textarea><small>Este cuadro es para carga masiva o edición de nombres.</small></label><label>Asesor en prevención<input name="safetyAdvisorName" value="${c.safetyAdvisorName||''}" placeholder="Nombre asesor"></label><label>Firma asesor prevención<input type="file" accept="image/*" data-advisor-signature="${id}"></label></div><div class="card" style="margin-top:16px"><h2 class="section-title">Firmas</h2>${workers.length?workers.map(w=>`<div class="config-item signature-only-row"><div><strong>Firma de ${w.name}</strong><small>Estado: <span style="color:${state.workerSignatures[w.name]?'#16713c':'#b42318'}">${state.workerSignatures[w.name]?'cargada':'pendiente'}</span></small></div><input type="file" accept="image/*" data-worker-signature="${id}" data-worker-name="${w.name}"></div>`).join(''):'<p class="empty">Guarda trabajadores para cargar sus firmas.</p>'}</div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Guardar listas</button></div></form>`)}
function newCenterModal(){modal('Nueva bodega / centro de costo',`<p class="page-subtitle">Crea una bodega u obra para asignar activos, stock, inspectores, aprobadores y trabajadores. Por trazabilidad, la eliminación quedará deshabilitada.</p><form id="newCenterForm"><div class="form-grid"><label class="full">Nombre de bodega o centro de costo<input name="name" required placeholder="Ej. Terra Túnel"></label><label>Inspectores<textarea name="inspectors" placeholder="Nombre Apellido"></textarea></label><label>Aprobadores<textarea name="approvers" placeholder="Nombre Apellido"></textarea></label><label class="full">Trabajadores<textarea name="workers" placeholder="Nombre Apellido | correo@empresa.cl | 56912345678"></textarea></label></div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Crear bodega</button></div></form>`)}
function deadlineModal(id){let i=state.inspections.find(x=>x.id===id),a=state.assets.find(x=>x.id===i.assetId);modal(`Plazo de corrección · ${a.code}`,`<p class="page-subtitle">El aprobador <strong>${i.approver}</strong> define la fecha máxima para corregir el incumplimiento.</p><form id="deadlineForm" data-id="${id}"><label>Fecha límite de ejecución<input type="date" name="due" required min="2026-06-24"></label><label style="margin-top:14px">Instrucción del aprobador<textarea name="instruction" required placeholder="Acción correctiva requerida y condición para liberar el equipo."></textarea></label><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Aprobar plazo</button></div></form>`)}
function correctionModal(id){let i=state.inspections.find(x=>x.id===id),a=state.assets.find(x=>x.id===i.assetId);modal(`Registrar corrección · ${a.code}`,`<p class="page-subtitle">Registra el levantamiento de la observación de la inspección del ${i.date}. El equipo quedará En revisión hasta la validación del revisor.</p><form id="correctionForm" data-id="${id}"><div class="form-grid"><label>Fecha del levantamiento<input type="date" name="date" required value="2026-06-24"></label><label>Ejecutado por<input name="performedBy" required value="${activeUser().name}"></label><label class="full">Corrección realizada<textarea name="notes" required placeholder="Describe la acción correctiva ejecutada.">${i.correctionNotes||''}</textarea></label><label class="full">Evidencia digital<input type="file" name="evidence" accept="application/pdf,image/*,.doc,.docx" required><small>Adjunta fotografía, PDF u otro respaldo del levantamiento.</small></label></div><div class="form-actions"><button type="button" class="outline" data-close>Cancelar</button><button class="button">Guardar levantamiento</button></div></form>`) }
let securityUsers=[],enrolledWorkers=[],securityDataLoaded=false,securityDataLoading=false;
async function loadSecurityData(force=false){if(!window.ICCAuth?.configured||!activeUserId||securityDataLoading||(!force&&securityDataLoaded))return;securityDataLoading=true;try{let calls=[fetch('/api/workers').then(r=>r.ok?r.json():Promise.reject(new Error('No se pudieron cargar trabajadores.')))];if(can('admin'))calls.push(fetch('/api/admin/users').then(r=>r.ok?r.json():Promise.reject(new Error('No se pudieron cargar usuarios.'))));let values=await Promise.all(calls);enrolledWorkers=values[0].workers||[];if(values[1])securityUsers=values[1].users||[];securityDataLoaded=true;if(route==='settings')render()}catch(err){toast(err.message)}finally{securityDataLoading=false}}
async function logisticsFetch(url,options={}){let controller=new AbortController(),timer,timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(new Error(`La consulta ${url} tardó más de 20 segundos. Revisa el despliegue de Render y vuelve a intentar.`))},20000)});try{let request=fetch(url,{...options,signal:controller.signal}),res=await Promise.race([request,timeout]),payload=await res.json().catch(()=>({}));if(!res.ok)throw new Error(payload.error||`No se pudo consultar ${url} (HTTP ${res.status}).`);return payload}finally{clearTimeout(timer)}}
async function loadLogisticsV2(force=false){if(!activeUserId||logisticsV2.loading||(!force&&logisticsV2.loaded))return;logisticsV2.loading=true;logisticsV2.error='';if(['reports','settings'].includes(route))render();try{let bundle=await logisticsFetch('/api/v1/logistics/dashboard',{headers:{'X-Legacy-User-Id':activeUserId}});logisticsV2={...logisticsV2,loaded:true,loading:false,status:bundle.status||null,items:bundle.items||[],warehouses:bundle.warehouses||[],stock:bundle.stock||[],transfers:bundle.transfers||[],custody:bundle.custody||[],workers:bundle.workers||[],reconciliation:bundle.reconciliation||null,error:''};if(['reports','settings'].includes(route))render()}catch(err){logisticsV2.loading=false;logisticsV2.error=err.message||'No fue posible cargar el modelo logístico.';if(['reports','settings'].includes(route))render()}}
function canonicalItemForAsset(a){let base=normalizeCode(assetBaseCode(a));return logisticsV2.items.find(item=>normalizeCode(item.sku)===base)||logisticsV2.items.find(item=>(item.units||[]).some(unit=>codeMatches(unit.unitCode,a.code)))}
function canonicalUnitForAsset(item,a){return (item?.units||[]).find(unit=>codeMatches(unit.unitCode,a.code))||null}
function canonicalWarehouse(name){let normalized=String(name||'').trim().toLowerCase();return logisticsV2.warehouses.find(w=>String(w.cost_center||w.name).trim().toLowerCase()===normalized)||null}
function canonicalLocation(name,type){let warehouse=canonicalWarehouse(name),locations=warehouse?.locations||[];return locations.find(location=>!type||location.type===type)||locations[0]||null}
function canonicalWorker({worker,email,phone,center}){let clean=v=>String(v||'').trim().toLowerCase(),digits=v=>String(v||'').replace(/\D/g,'');return (logisticsV2.workers||[]).find(w=>clean(w.cost_center)===clean(center)&&((email&&clean(w.email)===clean(email))||(phone&&digits(w.phone)===digits(phone))||clean(w.name)===clean(worker)))||null}
async function registerTerrainV2({legacyId,a,qty,from,worker,email,phone,notes,acceptanceToken}){if(!activeUserId)return null;if(!logisticsV2.loaded)await loadLogisticsV2(true);if(logisticsV2.error)throw new Error(`Libro mayor no disponible: ${logisticsV2.error}`);let item=canonicalItemForAsset(a),unit=canonicalUnitForAsset(item,a),warehouse=canonicalWarehouse(from),person=canonicalWorker({worker,email,phone,center:from});if(!item)throw new Error(`El artículo ${a.code} todavía no existe en el catálogo V2.`);if(!warehouse)throw new Error(`La bodega ${from} no existe en el modelo V2.`);if(!person)throw new Error(`${worker} debe estar enrolado en ${from} antes de registrar la entrega.`);let result=await logisticsFetch('/api/v1/custody',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:logisticsV2.status?.organizationId,itemId:item.id,assetUnitId:unit?.id||null,workerId:person.id,warehouseId:warehouse.id,quantity:a.type==='Activo'?1:qty,externalReference:`legacy-terrain:${legacyId}`,acceptanceToken,source:'QR',notes})});logisticsV2.loaded=false;return{custodyId:result.assignment?.id,movementId:result.movement?.id,kind:result.assignment?.assignment_type}}
function logisticsPanelMarkup(){let r=logisticsV2.reconciliation,s=r?.summary||{},diff=(r?.differences||[]).filter(x=>x.status==='DIFFERENCE'),stock=logisticsV2.stock||[],transfers=logisticsV2.transfers||[];if(logisticsV2.loading)return `<section id="logisticsV2Panel" class="card" style="margin-top:20px"><h2 class="section-title">Modelo logístico V2</h2><p class="page-subtitle">Consultando libro mayor y conciliación…</p></section>`;if(logisticsV2.error)return `<section id="logisticsV2Panel" class="card alert-card" style="margin-top:20px"><h2 class="section-title">Modelo logístico V2</h2><p class="page-subtitle">${htmlSafe(logisticsV2.error)}</p><button class="button secondary" data-refresh-logistics>Reintentar</button></section>`;if(!logisticsV2.loaded)return `<section id="logisticsV2Panel" class="card" style="margin-top:20px"><h2 class="section-title">Modelo logístico V2</h2><p class="page-subtitle">Preparando conciliación…</p></section>`;return `<section id="logisticsV2Panel" class="card logistics-v2" style="margin-top:20px"><div class="heading-row"><div><p class="eyebrow">Libro mayor transaccional</p><h2 class="section-title">Control logístico V2</h2><p class="page-subtitle">Los datos siguientes provienen de las tablas normalizadas y movimientos inalterables.</p></div><button class="button secondary" data-refresh-logistics>Actualizar conciliación</button></div><div class="grid metrics"><div class="card"><div class="metric-label">Artículos maestros</div><div class="metric-value">${logisticsV2.status?.schema?.items||0}</div></div><div class="card"><div class="metric-label">Unidades serializadas</div><div class="metric-value">${logisticsV2.status?.schema?.asset_units||0}</div></div><div class="card"><div class="metric-label">Movimientos V2</div><div class="metric-value">${logisticsV2.status?.schema?.movements||0}</div></div><div class="card"><div class="metric-label">Conciliación</div><div class="metric-value">${r?(r.ok?'OK':diff.length):'—'}</div><div class="metric-foot ${diff.length?'alert':''}">${r?(r.ok?'Sin diferencias':`${diff.length} diferencia(s)`):'Sólo administrador'}</div></div></div>${r?`<div class="access-box ${r.ok?'':'warning-box'}"><strong>${r.ok?'Inventario conciliado':'Revisión requerida'}</strong><div>Anterior: ${s.legacyTotal||0} · Libro mayor: ${s.canonicalTotal||0} · Saldos comparados: ${s.comparedBalances||0}</div></div>`:''}${diff.length?`<div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>Código</th><th>Centro</th><th>Anterior</th><th>V2</th><th>Diferencia</th></tr></thead><tbody>${diff.slice(0,30).map(x=>`<tr><td><span class="code">${htmlSafe(x.sku)}</span></td><td>${htmlSafe(x.center)}</td><td>${x.legacyQuantity}</td><td>${x.canonicalQuantity}</td><td><strong>${x.delta>0?'+':''}${x.delta}</strong></td></tr>`).join('')}</tbody></table></div>`:''}<h3 class="section-title" style="margin-top:22px">Stock según libro mayor</h3>${stock.length?`<div class="table-wrap"><table><thead><tr><th>Artículo</th><th>Unidad</th><th>Bodega</th><th>Ubicación</th><th>Cantidad</th></tr></thead><tbody>${stock.slice(0,80).map(x=>`<tr><td><strong>${htmlSafe(x.item_name)}</strong><br><span class="code">${htmlSafe(x.sku)}</span></td><td>${htmlSafe(x.unit_code||x.lot_number||'—')}</td><td>${htmlSafe(x.warehouse_name||'—')}</td><td>${htmlSafe(x.location_name)} · ${htmlSafe(x.location_type)}</td><td><strong>${x.quantity}</strong></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Sin saldos visibles.</p>'}<h3 class="section-title" style="margin-top:22px">Traslados V2</h3>${transfers.length?transfers.slice(0,20).map(t=>`<div class="config-item"><div><strong>${htmlSafe(t.transfer_number)} · ${htmlSafe(t.status)}</strong><small>${htmlSafe(t.source_warehouse)} → ${htmlSafe(t.destination_warehouse)} · ${(t.lines||[]).length} línea(s)</small></div>${tag(t.status)}</div>`).join(''):'<p class="empty">Sin traslados en el modelo V2.</p>'}</section>`}
function custodyV2Markup(){let rows=logisticsV2.custody||[];if(!logisticsV2.loaded||logisticsV2.error)return'';return `<section class="card logistics-v2" style="margin-top:20px"><div class="heading-row"><div><p class="eyebrow">Responsabilidad individual</p><h2 class="section-title">Entregas activas a terreno</h2><p class="page-subtitle">Activos bajo custodia y EPP pendiente o aceptado. Los consumibles quedan en el libro mayor como consumo.</p></div><span class="tag ${rows.length?'warning':'ok'}">${rows.length} activa(s)</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Producto</th><th>Trabajador</th><th>Bodega</th><th>Tipo</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${htmlSafe(x.item_name)}</strong><br><span class="code">${htmlSafe(x.unit_code||x.sku)}</span></td><td>${htmlSafe(x.worker_name||'Sin identificar')}<br><small>${htmlSafe(x.worker_rut||x.worker_email||'')}</small></td><td>${htmlSafe(x.warehouse_name||x.cost_center||'—')}</td><td>${htmlSafe(x.assignment_type)}</td><td>${tag(x.status)}</td><td>${htmlSafe(String(x.created_at||'').slice(0,10))}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No hay activos o EPP actualmente asignados a trabajadores.</p>'}</section>`}
function renderLogisticsPanel(){if(!['reports','settings'].includes(route)||!activeUserId||$('#logisticsV2Panel'))return;$('#view')?.insertAdjacentHTML('beforeend',logisticsPanelMarkup()+custodyV2Markup());if(!logisticsV2.loaded&&!logisticsV2.loading&&!logisticsV2.error)loadLogisticsV2()}
async function registerMovementV2({legacyId,a,action,qty,from,to,status,notes}){if(!activeUserId)return null;if(!logisticsV2.loaded)await loadLogisticsV2(true);if(logisticsV2.error)throw new Error(`Libro mayor no disponible: ${logisticsV2.error}`);let item=canonicalItemForAsset(a),unit=canonicalUnitForAsset(item,a);if(!item)throw new Error(`El artículo ${a.code} todavía no existe en el catálogo V2.`);let sourceWarehouse=canonicalWarehouse(from),destinationWarehouse=canonicalWarehouse(to),sourceLocation=canonicalLocation(from),destinationLocation=canonicalLocation(to),payloadBase={organizationId:logisticsV2.status?.organizationId,itemId:item.id,assetUnitId:unit?.id||null,quantity:a.type==='Activo'?1:qty,source:'QR',notes,idempotencyKey:`legacy-ui:${legacyId}`};if(status==='En tránsito'&&sourceWarehouse&&destinationWarehouse){let created=await logisticsFetch('/api/v1/transfers',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:payloadBase.organizationId,transferNumber:`UI-${legacyId}`,sourceWarehouseId:sourceWarehouse.id,destinationWarehouseId:destinationWarehouse.id,notes,lines:[{itemId:item.id,assetUnitId:unit?.id||null,quantity:payloadBase.quantity}]})});let transfer=created.transfer;await logisticsFetch(`/api/v1/transfers/${encodeURIComponent(transfer.id)}/dispatch`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotencyKey:`legacy-ui:${legacyId}:dispatch`,source:'QR',notes})});logisticsV2.loaded=false;return{transferId:transfer.id,kind:'transfer'}}if(action==='Recepción de traslado'){let pending=(logisticsV2.transfers||[]).find(t=>['IN_TRANSIT','PARTIALLY_RECEIVED'].includes(t.status)&&String(t.destination_warehouse||'').toLowerCase()===String(to).toLowerCase()&&(t.lines||[]).some(line=>normalizeCode(line.sku)===normalizeCode(item.sku)&&(unit?codeMatches(line.unitCode,a.code):true)));if(!pending)throw new Error('No encontramos el traslado V2 pendiente para este artículo y destino. Actualiza la conciliación.');let line=(pending.lines||[]).find(x=>normalizeCode(x.sku)===normalizeCode(item.sku)&&(unit?codeMatches(x.unitCode,a.code):true));await logisticsFetch(`/api/v1/transfers/${encodeURIComponent(pending.id)}/receive`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idempotencyKey:`legacy-ui:${legacyId}:receive`,source:'QR',notes,lines:[{lineId:line.id,quantity:payloadBase.quantity}]})});logisticsV2.loaded=false;return{transferId:pending.id,kind:'receipt'}}let movementType=action==='Ingreso proveedor / compra'?'RECEIPT':action==='Ajuste de stock'?'ADJUSTMENT':action==='Devolución a bodega'?'CUSTODY_RETURN':'TRANSFER_RECEIPT';let body={...payloadBase,movementType,fromLocationId:action==='Ingreso proveedor / compra'||action==='Ajuste de stock'?null:sourceLocation?.id||null,toLocationId:destinationLocation?.id||null,referenceType:'legacy_ui',referenceId:legacyId};if(!body.toLocationId)throw new Error(`La bodega destino ${to} no tiene ubicación V2.`);if(!['RECEIPT','ADJUSTMENT'].includes(movementType)&&!body.fromLocationId)throw new Error(`La bodega origen ${from} no tiene ubicación V2.`);let result=await logisticsFetch('/api/v1/stock/movements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});logisticsV2.loaded=false;return{movementId:result.movement?.id,kind:'movement'}}
