async function terrainSubmit(e){
  if(e.target.id!=='terrainForm')return;
  e.preventDefault();
  e.stopImmediatePropagation();
  let submit=e.target.querySelector('button:not([type="button"])');
  if(submit?.disabled)return;
  if(submit){submit.disabled=true;submit.textContent='Registrando…'}
  let today=new Date().toISOString().slice(0,10),a=state.assets.find(x=>x.id===e.target.dataset.asset),d=new FormData(e.target),qty=Number(d.get('qty')||1),from=d.get('from'),[worker,email,phone,center]=String(d.get('worker')||'').split('|'),notes=d.get('notes')||'';
  if(!a||!worker){if(submit){submit.disabled=false;submit.textContent='Registrar entrega'}return toast('Selecciona trabajador.')}
  if(a.type==='Consumible'&&stockAt(a,from)<qty){if(submit){submit.disabled=false;submit.textContent='Registrar entrega'}return toast(`Stock insuficiente en ${from}. Disponible: ${stockAt(a,from)}`)}
  let epp=isEpp(a),token=`cargo-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,status=epp?'Pendiente aceptación':a.type==='Consumible'?'Entrega informada':'Cargo informado',assignment={id:`as${Date.now()}`,assetId:a.id,code:a.code,kind:a.type,worker,email,phone,center,from,qty,date:today,issuer:activeUser().name,notes,status,token};
  try{
    let canonical=await registerTerrainV2({legacyId:assignment.id,a,qty,from,worker,email,phone,notes,acceptanceToken:epp?token:''});
    assignment.canonicalCustodyId=canonical?.custodyId||'';
    assignment.canonicalMovementId=canonical?.movementId||'';
    state.assignments.unshift(assignment);
    addDocument(epp?'Solicitud aceptación EPP':'Entrega a terreno',`${a.code} · ${worker}`,'Entrega a terreno',assignment.id,{code:a.code,worker,center:from,status});
    let msgBase=`ICC Piping informa entrega a terreno.\nProducto: ${a.name}\nCódigo: ${a.code}\nCantidad: ${qty}\nTrabajador: ${worker}\nFecha: ${today}\nBodega/contrato: ${from}`;
    if(a.type==='Consumible'){
      setStockAt(a,from,stockAt(a,from)-qty);
      a.location=from;
      state.movements.unshift({id:`m${Date.now()}`,date:today,code:a.code,action:'Entrega a terreno',user:activeUser().name,from,to:worker,qty,status:'Entrega informada',detail:`${qty} unid. entregadas a ${worker} · ${from}${notes?` · ${notes}`:''}`,canonicalMovementId:canonical?.movementId||''});
    }else{
      a.custodyWorker=worker;
      a.custodyEmail=email;
      a.status='A cargo de trabajador';
      a.responsible=worker;
      state.movements.unshift({id:`m${Date.now()}`,date:today,code:a.code,action:'Entrega a terreno',user:activeUser().name,from,to:worker,qty:1,status,detail:`${epp?'EPP pendiente de aceptación':'Activo a cargo informado'} a ${worker}. Stock permanece en ${from}.${notes?` · ${notes}`:''}`,canonicalCustodyId:canonical?.custodyId||''});
    }
    let acceptUrl=assignmentUrl(assignment),msg=epp?`${msgBase}\n\nPara aceptar el cargo abre:\n${acceptUrl}`:msgBase;
    state.notifications=state.notifications||[];
    state.notifications.unshift({date:today,to:phone||email,reviewer:worker,assetId:a.id,status,url:epp?acceptUrl:''});
    await persistState();
    await loadLogisticsV2(true);
    $('#modal').className='modal-root';
    render();
    setTimeout(()=>modal(epp?'Solicitar aceptación EPP':'Informar entrega / cargo',`<p class="page-subtitle">${epp?'EPP: envía WhatsApp/SMS para que el trabajador acepte. Después de aceptar se podrá enviar correo informando lo aceptado.':'No se solicita aceptación. Estos botones solo informan la entrega/cargo al trabajador.'}</p><div class="info-grid"><div class="info-item"><small>Trabajador</small>${worker}</div><div class="info-item"><small>Teléfono</small>${phone||'No informado'}</div><div class="info-item"><small>Correo</small>${email||'No informado'}</div><div class="info-item"><small>Producto</small>${a.name}</div><div class="info-item"><small>Código</small><span class="code">${a.code}</span></div><div class="info-item"><small>Estado</small>${status}</div></div><div class="form-actions" style="justify-content:flex-start">${phone?`<a class="button" href="https://wa.me/${cleanPhone(phone)}?text=${encodeURIComponent(msg)}" target="_blank">Enviar WhatsApp</a><a class="button secondary" href="sms:${cleanPhone(phone)}?&body=${encodeURIComponent(msg)}">Enviar SMS</a>`:''}${email?`<a class="button secondary" href="mailto:${email}?subject=${encodeURIComponent((epp?'Solicitud aceptación EPP ':'Información entrega ')+a.code)}&body=${encodeURIComponent(msg)}">Correo informativo</a>`:''}<button class="button secondary" data-download-assignment="${assignment.id}">Descargar registro</button></div>`),0);
  }catch(err){
    toast(err.message||'No se pudo registrar la entrega a terreno.');
    if(submit){submit.disabled=false;submit.textContent='Registrar entrega'}
  }
}
