document.addEventListener('submit',e=>{if(e.target.id!=='assetForm')return;e.preventDefault();e.stopImmediatePropagation();let f=family($('#assetFamily').value),type=$('#assetType').value,units=type==='Activo'?Math.max(1,Number($('#assetUnits')?.value||1)):1,existing=state.assets.filter(a=>a.family===f.id).map(a=>String(a.baseCode||a.code).match(new RegExp(`^${f.prefix}[-\\s]*0*(\\d+)`,'i'))).filter(Boolean).map(m=>Number(m[1])),next=Math.max(0,...existing)+1,baseCode=`${f.prefix}-${String(next).padStart(6,'0')}`,technical={layers:$('#assetLayers').value,width:$('#assetWidth').value,length:$('#assetLength').value,capacity:$('#assetCapacity').value,isEpp:$('#assetIsEpp')?.checked||false},created=[];for(let i=1;i<=units;i++){let code=type==='Activo'&&units>1?`${baseCode}-${i}`:baseCode,a={id:`a${Date.now()}-${i}`,code,baseCode:units>1?baseCode:code,unitNo:units>1?i:1,unitCount:units,name:$('#assetName').value,family:f.id,type,serial:$('#assetSerial').value,brand:$('#assetBrand').value,status:type==='Activo'?'Operativo':'Disponible',location:$('#assetLocation').value,responsible:activeUser().name,nextInspection:type==='Activo'?'2026-07-24':'',stock:type==='Consumible'?Number($('#assetStock').value):1,minimum:Number($('#assetMin').value),stocks:{},...technical};a.stocks[a.location]=type==='Consumible'?Number($('#assetStock').value):1;a.stock=Object.values(a.stocks).reduce((sum,v)=>sum+Number(v||0),0);state.assets.push(a);created.push(a);state.movements.unshift({id:`m${Date.now()}-${i}`,date:new Date().toISOString().slice(0,10),code:a.code,action:'Ingreso a bodega',user:activeUser().name,from:'Registro inicial',to:a.location,qty:a.stock,status:'Recibido',detail:`Registro inicial · ${a.location}${units>1?` · Unidad ${i} de ${units}`:''}`})}save();$('#modal').className='modal-root';toast(units>1?`Códigos generados: ${baseCode}-1 a ${baseCode}-${units}`:`Código generado: ${baseCode}`);window.lifeId=created[0].id;route=type==='Activo'?'life':'inventory';render()},true);
document.addEventListener('submit',e=>{if(e.target.id!=='userForm')return;e.preventDefault();e.stopImmediatePropagation();let d=new FormData(e.target),id=e.target.dataset.id,old=id?state.users.find(x=>x.id===id):null,oldName=old?.name,role=d.get('role')||'Usuario',admin=role==='Administrador central',obj={id:id||`u${Date.now()}`,name:d.get('name'),costCenter:d.get('costCenter'),initials:String(d.get('initials')||'').toUpperCase(),pin:String(d.get('pin')||'1234'),admin,role},file=e.target.querySelector('input[type="file"]')?.files?.[0],finish=()=>{if(id)Object.assign(old,obj);else state.users.push(obj);if(oldName&&oldName!==obj.name&&state.workerSignatures?.[oldName]&&!state.workerSignatures[obj.name])state.workerSignatures[obj.name]=state.workerSignatures[oldName];audit('Usuario guardado',obj.name);save();$('#modal').className='modal-root';toast('Usuario guardado.');render()};if(file)readImage(file,data=>{state.workerSignatures[obj.name]=data;finish()});else finish()},true);
document.addEventListener('submit',e=>{if(e.target.id!=='cloneAssetForm')return;e.preventDefault();e.stopImmediatePropagation();let base=state.assets.find(x=>x.id===e.target.dataset.id),d=new FormData(e.target),qty=Math.max(1,Number(d.get('qty')||1)),location=d.get('location')||base.location||'Bodega Central';if(!base)return toast('No encontramos el activo base.');let baseCode=assetBaseCode(base),unitOf=a=>Number(a.unitNo||(a.code===baseCode?1:((String(a.code).match(/^.+-(\d+)$/)||[])[1]||1))),siblings=state.assets.filter(a=>assetBaseCode(a)===baseCode),maxUnit=Math.max(1,...siblings.map(unitOf)),total=maxUnit+qty;state.assets.forEach(a=>{if(assetBaseCode(a)===baseCode){a.baseCode=baseCode;a.unitCount=total;if(!a.unitNo)a.unitNo=unitOf(a)}});let created=[];for(let i=1;i<=qty;i++){let unit=maxUnit+i,code=`${baseCode}-${unit}`,a={...base,id:`a${Date.now()}-${unit}`,code,baseCode,unitNo:unit,unitCount:total,serial:'',location,responsible:activeUser().name,status:'Operativo',stocks:{},stock:1};a.stocks[location]=1;delete a.custodyWorker;delete a.custodyEmail;state.assets.push(a);created.push(a);state.movements.unshift({id:`m${Date.now()}-${unit}`,date:new Date().toISOString().slice(0,10),code,action:'Ingreso a bodega',user:activeUser().name,from:'Activo igual',to:location,qty:1,status:'Recibido',detail:`Unidad ${unit} de ${total} creada desde ${base.code}`})}save();closeModal();toast(`Unidades creadas: ${created[0].code} a ${created[created.length-1].code}`);route='inventory';render()},true);
async function uploadWorkerSignature(file,name,center){if(!file?.name)return{};let dataUrl=await readFileData(file),res=await fetch('/api/files/upload',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({filename:file.name,dataUrl,category:'firmas-trabajadores',ref:name,center,uploadedBy:activeUser().name})}),payload=await res.json();if(!res.ok)throw new Error(payload.error||'No se pudo guardar la firma.');return{signatureFileId:payload.id,signatureData:dataUrl}}
async function saveWorkerPayload(payload,id){let res=await fetch(id?`/api/workers/${encodeURIComponent(id)}`:'/api/workers',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await res.json();if(!res.ok)throw new Error(body.error||'No se pudo guardar el trabajador.');return body}
document.addEventListener('submit',async e=>{if(e.target.id!=='authUserForm')return;e.preventDefault();e.stopImmediatePropagation();let d=new FormData(e.target),id=e.target.dataset.id,payload={id:id||undefined,name:d.get('name'),email:d.get('email'),costCenter:d.get('costCenter'),role:d.get('role'),initials:String(d.get('initials')||'').toUpperCase()};try{let res=await fetch(id?`/api/admin/users/${encodeURIComponent(id)}`:'/api/admin/users/invite',{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),body=await res.json();if(!res.ok)throw new Error(body.error||'No se pudo guardar el usuario.');if(!id)toast(body.message||'Invitación enviada.');else toast('Usuario actualizado.');closeModal();securityDataLoaded=false;await loadSecurityData(true)}catch(err){toast(err.message)}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='workerEnrollmentForm')return;e.preventDefault();e.stopImmediatePropagation();let d=new FormData(e.target),id=e.target.dataset.id,file=d.get('signature'),payload={name:d.get('name'),rut:d.get('rut'),company:d.get('company'),jobTitle:d.get('jobTitle'),costCenter:d.get('costCenter'),email:d.get('email'),phone:d.get('phone'),createAccess:d.get('createAccess')==='on'};try{if(file?.name)Object.assign(payload,await uploadWorkerSignature(file,payload.name,payload.costCenter));await saveWorkerPayload(payload,id);let c=state.costCenters.find(x=>x.name===payload.costCenter);if(c&&!c.workers.some(raw=>parseWorker(raw,c).name.toLowerCase()===String(payload.name).toLowerCase()))c.workers.push(`${payload.name} | ${payload.email||''} | ${payload.phone||''}`);if(payload.signatureData)state.workerSignatures[payload.name]=payload.signatureData;save();closeModal();securityDataLoaded=false;await loadSecurityData(true);toast(payload.signatureData?'Trabajador enrolado con firma.':'Trabajador enrolado; firma pendiente.')}catch(err){toast(err.message)}},true);
document.addEventListener('submit',async e=>{if(e.target.id!=='workerBulkForm')return;e.preventDefault();e.stopImmediatePropagation();let d=new FormData(e.target),center=d.get('costCenter'),rows=String(d.get('workers')||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);try{for(const row of rows){let[name,rut,company,jobTitle,email,phone]=row.split('|').map(x=>x.trim());await saveWorkerPayload({name,rut,company,jobTitle,email,phone,costCenter:center});let c=state.costCenters.find(x=>x.name===center);if(c&&name&&!c.workers.some(raw=>parseWorker(raw,c).name.toLowerCase()===name.toLowerCase()))c.workers.push(`${name} | ${email||''} | ${phone||''}`)}save();closeModal();securityDataLoaded=false;await loadSecurityData(true);toast(`${rows.length} trabajador(es) enrolados.`)}catch(err){toast(err.message)}},true);
document.addEventListener('click',async e=>{let t=e.target;try{if(t.dataset.newAuthUser!==undefined)authUserModal();if(t.dataset.editAuthUser)authUserModal(t.dataset.editAuthUser);if(t.dataset.newWorker!==undefined)workerModal();if(t.dataset.editWorker)workerModal(t.dataset.editWorker);if(t.dataset.bulkWorkers!==undefined)bulkWorkersModal();if(t.dataset.reinviteUser){let u=securityUsers.find(x=>x.id===t.dataset.reinviteUser);if(!u)return;let res=await fetch('/api/admin/users/invite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:u.id,name:u.name,email:u.email,role:u.role,costCenter:u.cost_center,initials:u.initials})}),body=await res.json();if(!res.ok)throw new Error(body.error);toast(body.message||'Enlace enviado.');securityDataLoaded=false;await loadSecurityData(true)}if(t.dataset.toggleAuthUser){let active=t.dataset.active==='true',u=securityUsers.find(x=>x.id===t.dataset.toggleAuthUser),res=await fetch(`/api/admin/users/${encodeURIComponent(u.id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:u.name,role:u.role,costCenter:u.cost_center,initials:u.initials,active:!active})}),body=await res.json();if(!res.ok)throw new Error(body.error);securityDataLoaded=false;await loadSecurityData(true);toast(active?'Usuario deshabilitado.':'Usuario reactivado.')}if(t.dataset.taskId&&t.dataset.taskStatus){await window.ICCAuth.updateTask(t.dataset.taskId,t.dataset.taskStatus);toast('Tarea actualizada.')}if(t.dataset.notificationRead){await window.ICCAuth.markNotification(t.dataset.notificationRead)}if(t.dataset.refreshRealtime!==undefined){await window.ICCAuth.refreshRealtime();toast('Información actualizada.')}}catch(err){toast(err.message||'No se pudo completar la acción.')}},true);
document.addEventListener('click',async e=>{if(e.target.dataset.refreshLogistics===undefined)return;e.preventDefault();logisticsV2.loaded=false;await loadLogisticsV2(true);toast(logisticsV2.error?logisticsV2.error:'Libro mayor y conciliación actualizados.')},true);
$('#userSwitcher').onclick=()=>{activeUserId?logout():(route='login',render())};$('#profileButton').onclick=()=>{activeUserId?(route='settings',render()):(route='login',render())};
async function loadRemoteState(){let res=await fetch('/api/state');if(!res.ok)return false;let payload=await res.json();if(payload?.state){state=repairTextState(payload.state);ensureInventoryModel();let authUser=window.ICCAuth?.appUser?.();if(authUser&&!state.users.some(u=>u.id===authUser.id))state.users.unshift(authUser);localStorage.setItem(storageKey,JSON.stringify(state));openAssetFromUrl();return true}return false}
function applyAuthenticatedUser(user){logisticsV2={loaded:false,loading:false,status:null,items:[],warehouses:[],stock:[],transfers:[],custody:[],workers:[],reconciliation:null,error:''};if(user){let existing=state.users.find(u=>u.id===user.id);if(existing)Object.assign(existing,user);else state.users.unshift(user);activeUserId=user.id;localStorage.setItem('control-activos-session',activeUserId);if(!openAssetFromUrl())route='dashboard';securityDataLoaded=false;loadRemoteState().finally(()=>{if(!openAssetFromUrl()&&requestedQrCode)route='scan';render()})}else if(window.ICCAuth?.configured&&window.ICCAuth.migrationComplete){activeUserId='';localStorage.removeItem('control-activos-session');route='login';render()}else render()}
window.addEventListener('icc-auth-error',e=>toast(e.detail));
window.addEventListener('icc-realtime',()=>{renderRealtimeCounter();if(route==='tasks')render()});
window.addEventListener('icc-public-accepted',e=>{$('#view').innerHTML=`<div class="card auth-card"><h1 class="page-title">Entrega aceptada</h1><p class="page-subtitle">${htmlSafe(e.detail||'El registro fue guardado correctamente.')}</p></div>`;toast(e.detail||'Cargo aceptado.')});
async function startApplication(){render();await window.ICCAuth.init(applyAuthenticatedUser);let params=new URLSearchParams(location.search),accept=params.get('accept');if(accept&&!window.ICCAuth.profile){window.acceptanceToken=accept;route='accept';try{let res=await fetch(`/api/public/acceptance?token=${encodeURIComponent(accept)}`),payload=await res.json();if(res.ok)window.publicAcceptance=payload}catch{}render();return}if(window.ICCAuth.profile&&!window.ICCAuth.passwordSetup){applyAuthenticatedUser(window.ICCAuth.appUser());return}if(!window.ICCAuth.configured||!window.ICCAuth.migrationComplete){await loadRemoteState();openAssetFromUrl()}else{activeUserId='';route='login'}render()}
startApplication();
